-- Shared text keys; keep both catalogs in sync.
local SAK = SkillsAlreadyKnown
if SAK.disabledByDev then return end
SAK.Translations = SAK.Translations or {}

SAK.Translations["en-EN"] = {
  ["\nCommande : "] = "\nCommand: ",
  ["\nTu peux cocher plusieurs choix."] = "\nYou can select several choices.",
  [" accessible à ton niveau, pas encore appris."] = " is accessible at your level and not yet learned.",
  [" appris. "] = ". ",
  [" — rang "] = " — rank ",
  [". Il s'agit d'une sélection initiale, pas d'un historique d'achats."] = ". This is an initial selection, not a purchase history.",
  [". Les prochains apprentissages remplaceront cette liste."] = ". Your next learning will replace this list.",
  [". Niveau requis : "] = ". Required level: ",
  [". Vérifie le prix chez le maître de classe."] = ". Check the price at your class trainer.",
  ["/sam conflicts (ou /samconflicts)"] = "/sam conflicts (or /samconflicts)",
  ["/sam conflicts — compatibilité"] = "/sam conflicts — compatibility",
  ["/sam debug — maître de classe"] = "/sam debug — class trainer",
  ["/sam pet — sorts du familier"] = "/sam pet — pet spells",
  ["/sam petdebug — grimoires du familier"] = "/sam petdebug — pet grimoires",
  ["/sam settings — options, rôles et spécialisations"] = "/sam settings — options, roles and specializations",
  ["1. Reproduis le problème avec la fenêtre concernée ouverte : maître de classe, marchand ou sacs."] = "1. Reproduce the issue with the affected window open: trainer, merchant or bags.",
  ["2. Ouvre le rapport correspondant, puis utilise son export pour copier le texte."] = "2. Open the matching report and use its export to copy the text.",
  ["3. Si nécessaire, compare après avoir désactivé manuellement un addon suspect et rechargé l'interface. Un addon présent dans le rapport n'est pas une preuve de conflit."] = "3. If needed, compare after manually disabling a suspected addon and reloading. An addon appearing in the report is not proof of a conflict.",
  ["A maintenir si combats contre morts-vivants ou demons."] = "Keep for fights against undead or demons.",
  ["ALREADY KNOWN : recettes déjà apprises dans les sacs et les jets de dés reconnus."] = "ALREADY KNOWN: learned recipes in bags and supported loot-roll windows.",
  ["ALREADY KNOWN signale automatiquement les recettes déjà apprises dans les sacs et les fenêtres de jet de dés de groupe ou raid, lorsque l’infobulle du jeu le confirme."] = "ALREADY KNOWN automatically marks learned recipes in bags and group or raid loot-roll windows when the game's tooltip confirms them.",
  ["Absorbe des dégâts et sécurise les incantations dans les deux activités."] = "Absorbs damage and protects casting in both activities.",
  ["Accéder aux rapports copiables du grimoire, des maîtres, des familiers et de compatibilité depuis Diagnostics."] = "Open copyable spellbook, trainer, pet and compatibility reports from Diagnostics.",
  ["Accélère les incantations après un critique, pour soigner ou attaquer."] = "Speeds up casts after a critical hit, for healing or attacking.",
  ["Active séparément les ajouts visuels de l'addon. Ces choix sont enregistrés pour ce personnage et s'appliquent immédiatement aux fenêtres ouvertes ; les icônes et textes du jeu restent disponibles."] = "Control the addon's visual additions separately. Settings are saved for this character and apply immediately to open windows; the game's icons and text remain available.",
  ["Active « Afficher tous les rangs » dans les options du grimoire du jeu pour voir les anciens rangs. Exemple : Plaie d'agonie affiche BEST sur le plus haut rang appris et LOW sur les autres, sans ECO."] = "Enable Show all ranks in the game's spellbook options to see older ranks. Example: Curse of Agony shows BEST on the highest learned rank and LOW on the others, without ECO.",
  ["Activer les conseils ECO"] = "Enable ECO advice",
  ["Activer ou désactiver les icônes, contours, textes et fonds de statut depuis Affichage, avec des explications et des aperçus."] = "Enable or disable icons, outlines, text and status backgrounds in Display, with explanations and previews.",
  ["Activité"] = "Activity",
  ["Actualisation des marqueurs lorsque les livres sont déplacés ou que les sorts du familier changent."] = "Refresh markers when books move or pet spells change.",
  ["Actualiser"] = "Refresh",
  ["Actualiser les marqueurs"] = "Refresh markers",
  ["Affaiblissement et dégâts utiles en PvE comme contre les joueurs."] = "Debuffs and damage useful in PvE and against players.",
  ["Affaiblissements et protections utiles pour sécuriser les combats."] = "Debuffs and protections help secure fights.",
  ["Affaiblit les ennemis sensibles ; intérêt aussi en soutien PvE."] = "Weakens susceptible enemies; also useful as PvE support.",
  ["Affichage"] = "Display",
  ["Affichage : icônes par zone, contours, textes et fonds réglables séparément."] = "Display: separate controls for icons by zone, outlines, text and backgrounds.",
  ["Affichage plus fluide et moins de défauts visuels pendant le défilement des sorts chez le maître de classe."] = "Smoother display and fewer visual glitches while scrolling class-trainer spells.",
  ["Afficher ALREADY KNOWN dans les sacs et les fenêtres de jet de dés lorsque l’infobulle du jeu confirme que la recette est déjà connue. Aucun survol ni scan de métier n’est nécessaire. L’absence de cette indication ne signifie pas que la recette est apprenable."] = "Show ALREADY KNOWN in bags and loot-roll windows when the game's tooltip confirms the recipe is learned. No mouseover or profession scan is required. An absent marker does not mean the recipe can be learned.",
  ["Afficher ALREADY KNOWN sur les recettes déjà apprises dans les fenêtres de butin du jeu. Ne change aucun choix Besoin, Cupidité ou Passer."] = "Show ALREADY KNOWN on learned recipes in game loot-roll windows. Never changes Need, Greed or Pass choices.",
  ["Afficher BUY NEW RANK sur le plus haut rang appris si un rang supérieur est accessible à ton niveau et n'est pas classé facultatif pour ton rôle. Les prix ne sont pas vérifiés. Catalogue fourni par TrainerSpells s'il est chargé ; sinon, informations observées chez le maître actuellement ouvert. Les données incertaines n'entraînent pas d'alerte."] = "Show BUY NEW RANK on your highest learned rank when a higher rank is accessible at your level and is not optional for your role. Prices are not checked. Uses TrainerSpells if loaded; otherwise, information from the currently open trainer. Uncertain data stays unmarked.",
  ["Afficher NEW +, la coche, NEXT, NOT NOW, ECO, BEST, OPTIONAL, BUY NEW RANK et LOW, ainsi que les marqueurs de livres et de démons. Désactiver retire aussi le halo de NEW + et les surimpressions assombries ; les icônes d'origine restent visibles."] = "Show NEW +, the check, NEXT, NOT NOW, ECO, BEST, OPTIONAL, BUY NEW RANK and LOW, plus book and demon markers. Disabling also removes the NEW + glow and dark overlays; original game icons remain visible.",
  ["Afficher RECENT sur les recettes récemment apprises dans les listes de métiers du jeu reconnues."] = "Show RECENT on recently learned recipes in supported game profession lists.",
  ["Afficher le bouton de minicarte"] = "Show minimap button",
  ["Afficher le résumé et la liste des commandes dans une fenêtre séparée."] = "Show the summary and command list in a separate window.",
  ["Afficher les badges des sorts, les icônes de la légende et l’indication de rôle à gauche du titre de spécialisation du grimoire."] = "Show spell badges, legend icons and the specialization role beside the spellbook title.",
  ["Afficher les badges des sorts, les repères PVP / PVE PVP, les surimpressions et le halo NEW + chez le maître de classe."] = "Show spell badges, PVP / PVE PVP markers, overlays and the NEW + glow at class trainers.",
  ["Afficher les conseils OPTIONAL"] = "Show OPTIONAL advice",
  ["Afficher les indications de rôle à côté des titres et les repères PVP / PVE PVP sur les talents, avec leurs infobulles."] = "Show role labels beside tree titles and PVP / PVE PVP talent markers with tooltips.",
  ["Afficher les marqueurs de livres dans les sacs, la banque et la banque de guilde, y compris les sacs EllesmereUI."] = "Show book markers in bags, the bank and guild bank, including EllesmereUI bags.",
  ["Afficher les marqueurs de livres et de démons chez le marchand."] = "Show book and demon markers at merchants.",
  ["Afficher les repères PVP / PVE PVP"] = "Show PVP / PVE PVP markers",
  ["Afficher séparément les icônes par zone : grimoire, maître de classe, marchand, sacs et banques, arbre de talents."] = "Control icons separately in the spellbook, at trainers and merchants, in bags and banks, and in talent trees.",
  ["Affliction offre une progression régulière avec les dégâts sur la durée et les drains. Démonologie devient plus intéressante lorsque ses talents renforçant le démon sont obtenus ; son début de parcours est plus lent."] = "Affliction provides steady progress through damage over time and drains. Demonology becomes more appealing after gaining pet-strengthening talents; its early progression is slower.",
  ["Aide surtout à se dégager des joueurs au corps à corps."] = "Mainly helps escape players in melee range.",
  ["Aide à continuer ses incantations lorsque l’on subit des attaques."] = "Helps you keep casting while taking attacks.",
  ["Aide à retrouver rapidement un démon après sa perte."] = "Helps restore a demon quickly after losing it.",
  ["Aide à retrouver sa mobilité pour poursuivre ou se dégager."] = "Restores mobility sooner for pursuit or escape.",
  ["Aide à récupérer de la mana entre les ennemis ou les engagements PvP."] = "Helps recover mana between enemies or PvP engagements.",
  ["Aider dans un autre rôle ne remplace pas un équipement et des talents adaptés."] = "Helping in another role does not replace suitable gear and talents.",
  ["Ajouter ECO / OPTIONAL et PVP / PVE PVP aux sorts renseignés dans la liste de classe de TrainerSpells, selon tes rôles et réglages. Son propre affichage de disponibilité reste conservé."] = "Add ECO / OPTIONAL and PVP / PVE PVP to reviewed spells in the TrainerSpells class list, according to your roles and settings. Its availability display stays unchanged.",
  ["Ajouter les contours de statut chez le maître de classe et autour des livres reconnus chez le marchand et dans les sacs. Désactiver retire uniquement les contours de notre addon."] = "Add status outlines at trainers and around recognized books at merchants and in bags. Disabling removes only this addon's outlines.",
  ["Ajouter un fond vert discret aux lignes apprenables, jaune aux prochains paliers et sombre aux sorts déjà appris. Ce réglage est indépendant des contours et des icônes ; il ne modifie pas le fond général des fenêtres."] = "Add subtle green backgrounds to learnable rows, yellow to the next tier and dark backgrounds to learned spells. Independent of outlines and icons; does not change the windows' overall background.",
  ["Ajouts de fonctionnalités"] = "New features",
  ["Alternance de sorts qui donne du rythme au jeu à distance."] = "Alternating spells gives ranged gameplay an engaging rhythm.",
  ["Amélioration"] = "Enhancement",
  ["Amélioration associe les attaques de mêlée aux renforcements d'arme, aux totems et aux occasions de lancer des sorts sans leur préparation habituelle. Les attaques automatiques gardent une place importante, ce qui laisse le temps d'apprendre à gérer le soutien du groupe. À mesure que les talents arrivent, il faut aussi réagir aux charges et aux effets qui rendent certains sorts plus avantageux."] = "Enhancement combines melee attacks, weapon buffs, totems and opportunities to cast spells without their usual preparation. Auto-attacks remain important, giving time to learn group support. Later talents require reacting to stacks and effects that improve certain spells.",
  ["Amélioration est un choix pratique dès les premiers niveaux : ses attaques d'arme, ses renforcements et ses soins permettent une progression autonome. Élémentaire reste une alternative à distance, plus attentive à sa dépense de mana."] = "Enhancement is practical from early levels: weapon attacks, buffs and healing support independent progress. Elemental is a ranged alternative requiring more attention to mana spending.",
  ["Annuler"] = "Cancel",
  ["Aperçu : aucun contour de statut ajouté."] = "Preview: no added status outline.",
  ["Aperçu : badge ajouté au-dessus du sort."] = "Preview: badge above the spell.",
  ["Aperçu : icône du sort seule, sans badge ajouté."] = "Preview: original spell icon without an added badge.",
  ["Aperçu : nom et informations d'origine, sans couleur ni annotation ajoutée."] = "Preview: original names and information without added colors or annotations.",
  ["Aperçu : |cff555555Sort appris|r  |cffff2626Sort indisponible|r  |cff40ff40[Already in your Bag]|r"] = "Preview: |cff555555Learned spell|r  |cffff2626Unavailable spell|r  |cff40ff40[Already in your Bag]|r",
  ["Aperçu schématique : |cff00ff00[ Apprenable ]|r  |cffffd100[ Prochain palier ]|r  |cffff3333[ Indisponible ]|r  |cff888888[ Appris ]|r"] = "Preview: |cff00ff00[ Learnable ]|r  |cffffd100[ Next tier ]|r  |cffff3333[ Unavailable ]|r  |cff888888[ Learned ]|r",
  ["Apprentissages récents"] = "Recent learning",
  ["Arbre de talents"] = "Talent trees",
  ["Arcanes"] = "Arcane",
  ["Arcanes fait de la mana une ressource à dépenser au bon moment : certains sorts augmentent la pression offensive mais rendent les enchaînements coûteux. Il faut alterner les phases de dépense avec des attaques plus économes et profiter des effets déclenchés par les talents. Le bon rythme dépend notamment de la durée du combat."] = "Arcane treats mana as a resource to spend at the right moment: some spells increase offensive pressure but make sequences expensive. Alternate spending phases with economical attacks and use talent-triggered effects. The right rhythm depends partly on fight length.",
  ["Armes"] = "Arms",
  ["Armes permet de se concentrer sur une bonne arme à deux mains. Fureur est une autre option, avec de nouveaux outils de récupération de vie, mais dépend fortement des armes et de l'équipement. Les deux demandent des combats bien choisis."] = "Arms lets you focus on a good two-handed weapon. Fury is an alternative with health-recovery tools but depends heavily on weapons and equipment. Both require choosing fights carefully.",
  ["Armes privilégie des coups puissants avec une arme à deux mains, tout en profitant de saignements et d'occasions d'attaquer. La rage gagnée au combat doit être utilisée au bon moment plutôt que dépensée sans réserve. Le guerrier dispose aussi de déplacements rapides et de contrôles qui l'aident à rester au contact de ses adversaires."] = "Arms favors powerful two-handed weapon strikes, bleeds and attack opportunities. Spend rage at the right time instead of emptying it indiscriminately. Rapid movement and control help the warrior stay in melee range.",
  ["Arrêter un lanceur de sorts peut aider en donjon comme en PvP."] = "Stopping a caster can help in dungeons and PvP.",
  ["Assassinat"] = "Assassination",
  ["Assassinat construit des points de combo avec ses attaques, puis les dépense surtout pour entretenir ses principaux effets offensifs. Dans Forever, le rythme décrit par le guide repose davantage sur le suivi de ces effets que sur une longue liste de grandes capacités à déclencher. C'est une approche assez directe, mais qui demande de surveiller son énergie et ses renouvellements."] = "Assassination builds combo points and spends them mainly to maintain key offensive effects. In Forever, the guide describes tracking these effects rather than juggling many major cooldowns. The approach is straightforward but requires attention to energy and refresh timing.",
  ["Attaque centrale du jeu Amélioration en PvE comme en PvP."] = "A central Enhancement attack in PvE and PvP.",
  ["Attaque de Destruction utile dans les deux activités."] = "A Destruction attack useful in both activities.",
  ["Attaque instantanée utilisée en PvE et pour finir un adversaire en PvP."] = "An instant attack used in PvE and to finish an opponent in PvP.",
  ["Attaque majeure en Armes ; sa pression sur les soins est précieuse en PvP."] = "A major Arms attack; its healing pressure is valuable in PvP.",
  ["Aucun apprentissage enregistré."] = "No learning recorded.",
  ["Aura de dévotion : le rang 1 peut suffire pendant le leveling Vindicte, hors rôle tank."] = "Devotion Aura: rank 1 may suffice while leveling Retribution, outside a tank role.",
  ["Automatique (client du jeu)"] = "Automatic (game client)",
  ["Avant le niveau 10, survoler un onglet de spécialisation du grimoire présente son résumé, ses avantages et ses inconvénients."] = "Before level 10, hovering a spellbook school tab shows its summary, advantages and drawbacks.",
  ["Avantages"] = "Advantages",
  ["Avantages et limites synthétisés depuis le gameplay décrit ; la rubrique dédiée du guide est absente ou incomplète."] = "Advantages and drawbacks summarized from the described gameplay; the guide's dedicated section is absent or incomplete.",
  ["Avec TrainerSpells actif, les textes du maître de classe restent sous son contrôle même si cette case est cochée. Les réglages des autres catégories restent indépendants."] = "With TrainerSpells enabled, trainer text remains under its control even if this option is checked. Other display settings remain independent.",
  ["BEST : plus haut rang appris.\nOPTIONAL : achat facultatif (rôle)."] = "BEST: highest learned rank.\nOPTIONAL: purchase can wait (role).",
  ["BUY NEW RANK — rang "] = "BUY NEW RANK — rank ",
  ["Bien utiliser les différentes portées et gérer le matériel demande de l’attention."] = "Managing different ranges and equipment requires attention.",
  ["Bon contrôle des groupes grâce aux ralentissements de zone."] = "Good control of groups through area slows.",
  ["Bon potentiel contre les groupes d’ennemis."] = "Good potential against groups of enemies.",
  ["Bon potentiel de dégâts concentrés lors des moments importants."] = "Strong concentrated damage during important moments.",
  ["Bon potentiel de dégâts à mesure que l’équipement progresse."] = "Good damage potential as equipment improves.",
  ["Bon potentiel en solo, avec plusieurs outils pour survivre."] = "Good solo potential with several survival tools.",
  ["Bonne capacité à concentrer rapidement ses dégâts."] = "Good ability to concentrate damage quickly.",
  ["Bonne capacité à protéger un allié en difficulté et à résister soi-même."] = "Strong protection for endangered allies and personal survival.",
  ["Bonne couverture des dégâts réguliers et soins ciblés disponibles en renfort."] = "Good coverage of steady damage, with targeted healing for support.",
  ["Bonne mobilité et capacité à concentrer ses attaques sur un moment précis."] = "Good mobility and concentrated attack windows.",
  ["Bonne résistance et soutien du familier pour progresser en solo."] = "Good durability and pet support for solo leveling.",
  ["Bonnes possibilités de dégâts sur quelques ennemis proches."] = "Good damage against a few nearby enemies.",
  ["Bonnes possibilités de frapper plusieurs ennemis proches."] = "Good ways to hit several nearby enemies.",
  ["Bons moments de dégâts renforcés et plusieurs moyens de garder ses distances."] = "Strong offensive windows and several ways to keep your distance.",
  ["Bonus de groupe et outils défensifs utiles pendant la progression."] = "Useful group buffs and defensive leveling tools.",
  ["Boucliers efficaces et bonne résistance personnelle."] = "Effective shields and good personal durability.",
  ["Capacité à concentrer des dégâts importants avec les tirs préparés."] = "Strong concentrated damage from prepared shots.",
  ["Capacités offensives utiles pour accélérer les dégâts à un moment choisi."] = "Offensive abilities accelerate damage at chosen moments.",
  ["Casting adverse/PvP; soin demon; quetes sous-marines; donjons et controle: condition par usage, pas par seule spe."] = "Enemy casting/PvP, demon healing, underwater quests, dungeons and control: decide by use, not specialization alone.",
  ["Ce conseil concerne ce rang, pas l'utilité du sort lui-même. Il ne signifie pas que le rang 1 suffit dans tous les cas."] = "This advice concerns this rank, not the usefulness of the spell itself. It does not mean rank 1 suffices in every situation.",
  ["Certaines attaques de zone imposent de s’approcher et de surveiller sa vie."] = "Some area attacks require moving close and watching your health.",
  ["Certains grands bonus offensifs reviennent lentement et ne sont pas disponibles à chaque combat."] = "Some major offensive boosts have long cooldowns and are not available every fight.",
  ["Ces boutons ouvrent les mêmes rapports copiables que les commandes du chat. Le panneau d'options se ferme pour laisser le rapport visible."] = "These buttons open the same copyable reports as chat commands. The options panel closes to leave the report visible.",
  ["Cet arbre ne dispose pas d’une véritable interruption de sort."] = "This tree lacks a true spell interrupt.",
  ["Cet arbre renforce le lien entre le démoniste et ses familiers : leurs dégâts, leur résistance et leurs bonus se complètent. Dans Forever, certains talents permettent de profiter d'un sacrifice tout en gardant un autre démon au combat. Le joueur entretient ses effets offensifs et doit aussi bien diriger et protéger son compagnon."] = "This tree strengthens the bond between warlock and demons: their damage, durability and buffs complement each other. In Forever, some talents allow benefiting from a sacrifice while keeping another demon in combat. Maintain offensive effects while directing and protecting your companion.",
  ["Chaman"] = "Shaman",
  ["Chasseur"] = "Hunter",
  ["Choisir la langue des options, conseils et infobulles. Un rechargement est nécessaire pour appliquer ce choix partout."] = "Choose the language for options, advice and tooltips. Reload the interface to apply this choice everywhere.",
  ["Choisir le bon outil selon la situation reste plus important que répéter un seul soin."] = "Choosing the right tool matters more than repeating one heal.",
  ["Choisir ses rôles et spécialisations dans l’onglet Talent Spec and Role, parmi les choix disponibles pour sa classe."] = "Choose roles and specializations available to your class in Talent Spec and Role.",
  ["Choisis où afficher les marqueurs de l'addon. Le réglage général Icônes et surimpressions reste prioritaire. Ces cases ne changent pas les contours ni la coloration des textes."] = "Choose where addon markers appear. The general Icons and overlays setting takes priority. These options do not change outlines or text coloring.",
  ["Choisis tes rôles parmi ceux de ta classe. Si plusieurs spécialisations sont possibles, sélectionne celle que tu suis. Au premier lancement, une spécialisation est proposée selon tes points de talents ; sans arbre dominant, le choix conseillé pour le leveling solo est proposé. Tu peux modifier cette sélection. Les conseils ne sont activés qu’après « Valider mes choix » puis OK dans le récapitulatif. Sans validation, cette fenêtre revient au prochain login ou /reload."] = "Choose roles available to your class. If several specializations are possible, select the one you follow. First use suggests one from your talent points, or the solo leveling recommendation if no tree dominates. You can change this selection. Advice activates only after Confirm my choices and OK in the recap. Without confirmation, this window returns at the next login or /reload.",
  ["Clic droit : résumé et commandes"] = "Right-click: summary and commands",
  ["Clic gauche : options"] = "Left-click: options",
  ["Coche verte et contour gris : sort déjà appris."] = "Green check and grey outline: already learned.",
  ["Colorer les textes lorsque c'est compatible, ajouter les mentions des livres, les compteurs de doublons, les informations dans les infobulles et les indications de rôle à droite des titres des arbres de talents. Désactiver retire nos ajouts ; les textes du jeu et des autres addons restent gérés par eux. Les prochaines infobulles reflètent ce choix. Avant le niveau 10, les onglets de spécialisation du grimoire présentent aussi leur résumé. ECO et OPTIONAL apparaissent aussi dans les infobulles de sorts hors du grimoire (barres d'action, liens de sorts compatibles), selon ton rôle."] = "Color text where compatible; add book labels, duplicate counts, tooltip information and talent-tree role labels. Disabling removes our additions; game and other addon text remains under their control. Newly opened tooltips reflect this choice. Before level 10, spellbook school tabs show specialization summaries. ECO and OPTIONAL also appear in recognized spell tooltips outside the spellbook, according to your roles.",
  ["Combat est un point de départ simple. Assassinat et Finesse restent des alternatives si tu préfères leurs mécanismes ; le conseil n'impose pas une spécialisation à tout le groupe."] = "Combat is a simple starting point. Assassination and Subtlety are alternatives if you prefer their mechanics; the advice does not impose a specialization on the whole group.",
  ["Combat favorise une approche directe du combat de mêlée, en construisant des points de combo pour entretenir sa vitesse d'attaque et lancer ses finitions. Il dispose de moments offensifs renforcés qu'il faut exploiter au bon moment. Les attaques automatiques occupent une place importante, et cet arbre dépend moins des poisons et saignements pour faire fonctionner son plan de jeu."] = "Combat takes a direct melee approach, building combo points to maintain attack speed and use finishers. Make good use of offensive windows. Auto-attacks matter greatly, and this tree relies less on poisons and bleeds for its core gameplay.",
  ["Combat propose un parcours direct, avec des talents défensifs et des outils pour interrompre ou fuir un combat dangereux. Les armes, les poisons et l'utilisation des contrôles comptent beaucoup."] = "Combat offers a straightforward path, defensive talents and ways to interrupt or escape dangerous fights. Weapons, poisons and control use matter greatly.",
  ["Commandes :"] = "Commands:",
  ["Compatibilité (/sam conflicts)"] = "Compatibility (/sam conflicts)",
  ["Comprendre les marqueurs"] = "Understand the markers",
  ["Comprendre les trois arbres de talents"] = "Understand the three talent trees",
  ["Confirmer tes choix pour "] = "Confirm your choices for ",
  ["Conseils : ECO = rang suffisant pour l'usage conseillé ; OPTIONAL = achat reportable selon tes rôles. L'économie concerne l'or d'apprentissage."] = "Advice: ECO = sufficient rank for the recommended use; OPTIONAL = a purchase that can wait for your roles. Savings concern training gold.",
  ["Conseils de leveling"] = "Leveling advice",
  ["Conserver les rangs inferieurs; ne signifie pas rang 1 suffisant."] = "Keep earlier ranks; this does not mean rank 1 suffices.",
  ["Consulter cet historique des ajouts et corrections dans l’onglet Patchnotes."] = "Read versioned new features and bug fixes in Patchnotes.",
  ["Consulter des conseils de spécialisation pour progresser en solo ou en groupe depuis les indications de rôle de l’arbre de talents."] = "Read solo and group leveling specialization advice from talent-tree role labels.",
  ["Consulter les observations de compatibilité de cette session."] = "View this session's compatibility observations.",
  ["Consulter les résumés des trois arbres, leurs avantages et leurs inconvénients dans les options et les infobulles de rôle de l’arbre de talents."] = "Read summaries of all three trees, their advantages and drawbacks in the options and talent-role tooltips.",
  ["Consulter les sorts du familier et les informations des grimoires avec /sak pet et /sak petdebug."] = "View pet spells and grimoire information with /sak pet and /sak petdebug.",
  ["Consulter les sorts enregistrés pour le familier actif."] = "View saved spells for the active pet.",
  ["Contours de couleur"] = "Colored outlines",
  ["Contrôle court pour interrompre une menace ou reprendre de la distance."] = "Brief control to stop a threat or regain distance.",
  ["Contrôle de zone utile sur les groupes d’ennemis et en combats PvP."] = "Area control useful against groups of enemies and in PvP.",
  ["Contrôle défensif utile lorsqu’un ennemi arrive au contact."] = "Defensive control useful when an enemy reaches melee range.",
  ["Contrôle utile contre les joueurs et pour retenir des ennemis en PvE."] = "Control useful against players and for holding enemies in PvE.",
  ["Contrôle, soutien ou mobilité utile en PvE comme en PvP, selon la cible."] = "Control, support or mobility useful in PvE and PvP, depending on the target.",
  ["Copier"] = "Copy",
  ["Copy Export"] = "Copy Export",
  ["Correction de la détection du niveau requis des grimoires dans l’inventaire."] = "Fixed grimoire required-level detection in inventory.",
  ["Corrections de bugs"] = "Bug fixes",
  ["Couleurs et annotations de texte"] = "Text colors and annotations",
  ["Cri psychique : le rang 1 garde un contrôle de secours ; les rangs suivants peuvent toucher davantage de cibles."] = "Psychic Scream: rank 1 keeps emergency control; later ranks can affect more targets.",
  ["Dans Forever, le coût en mana peut augmenter avec ton niveau même sans acheter de rang supérieur, selon le sort."] = "In Forever, mana costs may increase with your level even without buying a higher rank, depending on the spell.",
  ["Dans Forever, le coût en mana peut évoluer avec ton niveau selon le sort. ECO vise l'or d'apprentissage. BEST ne garantit pas de toucher ; un rang 1 conseillé garde ECO même si un rang supérieur affiche BEST."] = "In Forever, mana costs may scale with your level depending on the spell. ECO concerns training gold. BEST does not guarantee a hit; a recommended rank 1 keeps ECO even if a higher rank shows BEST.",
  ["Davantage de vie aide à survivre dans les deux activités."] = "More health helps survival in both activities.",
  ["Demande de surveiller plusieurs durées et plusieurs cibles."] = "Track several durations and targets.",
  ["Demande d’apprendre quel soin choisir plutôt que de répéter un seul sort."] = "Learn which heal to choose rather than repeating one spell.",
  ["Derniers apprentissages : RECENT"] = "Recent learning: RECENT",
  ["Des repères PVP et PVE PVP signalent l’usage conseillé des talents renseignés et des sorts apprenables chez le maître de classe, avec une explication au survol."] = "PVP and PVE PVP markers indicate suggested uses for reviewed talents and learnable trainer spells, with explanations on hover.",
  ["Destruction privilégie les sorts de feu et les dégâts directs, tout en maintenant certains effets sur la cible. Le jeu consiste à préparer ces effets, utiliser les attaques instantanées lorsqu'elles sont disponibles et compléter avec les sorts à incantation. Le démon reste présent, mais le rythme repose davantage sur les attaques du personnage."] = "Destruction favors Fire spells and direct damage while maintaining some target effects. Set up those effects, use instant attacks when available and fill with cast-time spells. The demon remains present, but the rhythm relies more on the character's attacks.",
  ["Discipline combine soins et absorption : les boucliers permettent d'éviter une partie des dégâts plutôt que de tout réparer ensuite. Le prêtre alterne ces protections avec ses soins et ses outils de soutien selon la situation. Il conserve assez de moyens offensifs et défensifs pour progresser seul, en plus de son rôle de soigneur en groupe."] = "Discipline combines healing and absorption: shields prevent some damage rather than repairing it afterward. Alternate protection, healing and support according to the situation. Offensive and defensive tools support solo leveling as well as group healing.",
  ["Discipline permet d'alterner dégâts et soins avec souplesse ; Sacré convient à un parcours centré sur les soins du groupe. Ce dernier tue généralement plus lentement en solo."] = "Discipline switches flexibly between damage and healing; Holy suits group-focused healing. Holy generally kills more slowly solo.",
  ["Documentation clarifiée pour les grimoires déjà possédés et les rapports d’assistance."] = "Clarified documentation for already-owned grimoires and support reports.",
  ["Douleur brûlante : le guide Affliction propose le rang 1 comme petit sort de finition. Ce conseil ne s'applique pas à Démonologie."] = "Searing Pain: the Affliction guide suggests rank 1 as a small finisher. This does not apply to Demonology.",
  ["Drain d'âme : le rang 1 suffit pour récupérer un fragment en fin de combat. Ce conseil ne compare pas les dégâts."] = "Drain Soul: rank 1 suffices for collecting a shard near the end of a fight. This advice does not compare damage.",
  ["Druide"] = "Druid",
  ["Dégâts de mêlée accompagnés de la polyvalence des formes du druide."] = "Melee damage with the flexibility of druid forms.",
  ["Dégâts solides sur une cible et outils renforcés pour achever un ennemi."] = "Solid single-target damage and improved finishing tools.",
  ["Dégâts sur une cible et sur des groupes, accompagnés d’un soutien varié."] = "Single-target and group damage with versatile support.",
  ["Démoniste"] = "Warlock",
  ["Démonologie"] = "Demonology",
  ["ECO et OPTIONAL doivent convenir à tous les rôles cochés. Si PvP est coché, ces conseils sont suspendus ; BEST et LOW continuent de comparer les rangs appris. Seuls les sorts vérifiés sont concernés."] = "ECO and OPTIONAL must suit every selected role. Selecting PvP suspends this advice; BEST and LOW still compare learned ranks. Only reviewed spells are included.",
  ["Effacer les choix de rôle et relancer la fenêtre de premier lancement ?"] = "Clear role choices and restart the first-use window?",
  ["Effacer les choix de rôle et rouvrir la fenêtre de lancement avec une nouvelle présélection. La fenêtre sera aussi réaffichée au prochain /reload. Les réglages d'affichage restent conservés."] = "Clear role choices and reopen the first-use window with a new suggestion. It also returns at the next /reload. Display settings are kept.",
  ["Effets offensifs accompagnés de soutien indirect au groupe."] = "Offensive effects with indirect group support.",
  ["En développement — après "] = "In development — after ",
  ["En forme de félin, Farouche utilise de l'énergie pour construire des points de combo, puis les dépenser sur ses attaques de finition. Forever ajoute des talents qui renforcent ses moments offensifs, sans reprendre à l'identique les changements de forme répétés de Classic. Le druide peut toujours sortir de sa forme ou passer en ours pour aider son groupe."] = "In Cat Form, Feral spends energy to build combo points and uses them on finishers. Forever adds offensive talent interactions rather than simply copying Classic's repeated shapeshifting. The druid can still leave form or shift into a bear to help the group.",
  ["Encaisser les attaques et garder les ennemis sur soi pour protéger le groupe."] = "Take attacks and hold enemies' attention to protect the group.",
  ["Entraves : le rang 1 conserve un contrôle de base ; les rangs suivants améliorent sa durée."] = "Shackle: rank 1 keeps basic control; later ranks improve duration.",
  ["Exploiter toute la polyvalence du druide demande de l’expérience."] = "Using the druid's full flexibility takes experience.",
  ["Exporter les données des grimoires et du familier."] = "Export pet and grimoire information.",
  ["Exporter les sorts du joueur, les services du maître et la correspondance des lignes."] = "Export player spells, trainer services and displayed row matching.",
  ["Facilite la pression sur la mana des adversaires joueurs."] = "Helps pressure enemy players' mana.",
  ["Facilite les ouvertures ; intérêt en solo et contre les joueurs."] = "Helps with openers, useful solo and against players.",
  ["Faible apport Affliction; guide privilegie Spellstone a partir de 36."] = "Limited Affliction benefit; the guide prefers Spellstone from level 36.",
  ["Faible priorite pendant le leveling Givre."] = "Low priority while leveling Frost.",
  ["Fait partie de tes derniers apprentissages enregistrés. La liste est conservée après rechargement."] = "Part of your latest recorded learning. The list is saved after reloads.",
  ["Familier utile pour la progression en solo et pour ses capacités particulières."] = "A helpful solo pet with useful special abilities.",
  ["Farouche"] = "Feral",
  ["Farouche DPS"] = "Feral DPS",
  ["Farouche DPS; poison selon contenu; Cower surtout inutile solo; pas une regle Equilibre ou soin."] = "Feral DPS; poison removal depends on content. Cower has little solo use. Not a general Balance or healing rule.",
  ["Farouche devient particulièrement intéressant avec la forme de félin et sa mobilité. Équilibre reste une alternative si tu préfères jouer à distance, en surveillant davantage la mana."] = "Feral becomes especially appealing with Cat Form and its mobility. Balance remains an alternative if you prefer ranged play, with closer attention to mana.",
  ["Farouche tank"] = "Feral tank",
  ["Farouche tank pour encaisser en donjon, Restauration pour soigner un groupe régulier. Un parcours centré sur les soins convient moins aux quêtes en solo."] = "Feral tank for dungeon tanking, Restoration for healing a regular group. A healing-focused path is less suited to solo questing.",
  ["Farouche tank; garder les premiers rangs; duree/fiabilite du controle a comparer."] = "Feral tank; keep initial ranks and compare control duration and reliability.",
  ["Farouche tank; usages hors forme et soutien de groupe peuvent justifier l'achat."] = "Feral tank; out-of-form utility and group support may justify the purchase.",
  ["Fermer"] = "Close",
  ["Fermer la fenêtre de premier lancement. Tu pourras choisir avec /sam settings."] = "Close the first-use window. You can choose later with /sam settings.",
  ["Feu"] = "Fire",
  ["Feu construit ses dégâts autour des coups critiques et des effets qu'ils déclenchent. Dans Forever, ces déclenchements accélèrent notamment les grosses incantations, tandis que certains effets sur la cible doivent être entretenus. Le joueur cherche à enchaîner ses attaques en profitant de ces occasions sans laisser tomber ses préparations."] = "Fire builds damage around critical hits and their triggered effects. In Forever, these effects can speed up major casts while other target effects need maintaining. Chain attacks through these opportunities without losing your setup.",
  ["Finesse"] = "Subtlety",
  ["Finesse s'appuie sur les saignements, les points de combo et l'utilisation du camouflage pour renforcer ses attaques. Le joueur entretient plusieurs effets, profite des ouvertures et peut réutiliser la disparition pour retrouver certaines attaques de camouflage. Dans Forever, cette voie ne se résume donc pas à préparer une seule grosse attaque d'ouverture."] = "Subtlety uses bleeds, combo points and stealth to strengthen attacks. Maintain several effects, exploit openings and use Vanish to regain stealth attacks. In Forever, this path is more than preparing a single powerful opener.",
  ["Finisher rapide optionnel pour le parcours Affliction seulement."] = "Optional quick finisher for the Affliction path only.",
  ["Fonctionnement de base abordable pour apprendre à tanker."] = "Approachable basics for learning to tank.",
  ["Fonctionnement de base accessible et priorités assez lisibles."] = "Approachable basics and clear priorities.",
  ["Fonds activés : vert pour l'apprentissage, jaune pour le prochain palier, sombre pour les sorts déjà connus."] = "Backgrounds enabled: green for learnable spells, yellow for the next tier, dark for known spells.",
  ["Fonds de statut"] = "Status backgrounds",
  ["Fonds désactivés : aucun fond de statut ajouté aux lignes."] = "Backgrounds disabled: no status backgrounds added to rows.",
  ["Fureur"] = "Fury",
  ["Fureur joue sur le rythme des attaques de mêlée et la dépense de rage, avec des capacités qui renforcent temporairement la pression offensive. Les dégâts contre quelques ennemis regroupés font partie de ses points forts. Le joueur doit surveiller sa ressource, utiliser ses attaques prioritaires et choisir quand profiter de ses grands bonus offensifs."] = "Fury focuses on melee attack rhythm and rage spending, with abilities that temporarily boost offensive pressure. Damage against a few grouped enemies is a strength. Watch resources, prioritize attacks and choose when to use major offensive boosts.",
  ["Givre"] = "Frost",
  ["Givre apporte du contrôle ; Arcanes peut enchaîner les combats avec ses outils de mana. Feu reste une option si tu préfères son jeu autour des critiques."] = "Frost brings control; Arcane can chain fights with its mana tools. Fire is an option if you prefer critical-hit gameplay.",
  ["Givre contrôle la distance avec des ralentissements et des immobilisations, puis exploite les occasions offertes par ses talents pour frapper plus fort. Ses protections permettent de mieux gérer les situations dangereuses. Le rythme de base reste accessible, mais tirer le meilleur de l'arbre demande de réagir aux effets temporaires qui apparaissent."] = "Frost controls distance through slows and roots, then uses talent opportunities to hit harder. Defensive tools help manage danger. The basics are approachable, but getting the most out of the tree means reacting to temporary effects.",
  ["Givre privilégie la sécurité grâce aux ralentissements et aux protections. Arcanes offre une alternative confortable pour les quêtes avec de bons outils de gestion de mana ; ce n'est pas le même compromis que dans Classic."] = "Frost favors safety through slows and protection. Arcane offers comfortable questing with good mana tools; the trade-off differs from Classic.",
  ["Grimoire"] = "Spellbook",
  ["Grimoire : BEST = plus haut rang appris ; LOW = ancien rang déjà remplacé ; BUY NEW RANK = rang supérieur accessible à apprendre."] = "Spellbook: BEST = highest learned rank; LOW = an older rank already replaced; BUY NEW RANK = an accessible upgrade remains to learn.",
  ["Grimoire du joueur (/sam bookdebug)"] = "Player spellbook (/sam bookdebug)",
  ["Grosse attaque utilisable en PvE et dans certaines combinaisons PvP."] = "A strong attack usable in PvE and some PvP combinations.",
  ["Guerrier"] = "Warrior",
  ["Guide des marqueurs — livres du familier et inventaire"] = "Marker guide — pet books and inventory",
  ["Guide des marqueurs — maîtres de classe"] = "Marker guide — class trainers",
  ["Heal"] = "Healer",
  ["Hors tanking; conserver si besoin de reprise ponctuelle."] = "Outside tanking; keep if you need occasional threat recovery.",
  ["Icônes et surimpressions"] = "Icons and overlays",
  ["Icônes par zone"] = "Icons by display zone",
  ["Identifier chez le marchand les grimoires déjà présents dans les sacs, avec une mention et un contour vert."] = "Identify grimoires already in your bags at merchants, with a label and green outline.",
  ["Identifier les grimoires démonistes déjà appris ou apprenables dans les sacs Blizzard et EllesmereUI, avec des marqueurs de démon et d’apprentissage."] = "Identify learned and learnable demon grimoires in Blizzard and EllesmereUI bags, with demon and learning markers.",
  ["Identifier les sorts du maître de classe avec NEW +, une coche verte, NEXT ou NOT NOW ; NEW + peut afficher un halo lumineux."] = "Identify trainer spells with NEW +, a green check, NEXT or NOT NOW; NEW + can glow.",
  ["Identifier les sorts déjà appris chez les maîtres de classe grâce à un texte gris et un fond assombri."] = "Identify learned trainer spells through grey text and a darkened background.",
  ["Il faut gérer la mana, les charges offensives et le placement des totems."] = "Manage mana, offensive stacks and totem positioning.",
  ["Il faut gérer la rage et les protections au rythme des attaques ennemies."] = "Manage rage and defenses in time with enemy attacks.",
  ["Il faut suivre les déclenchements et entretenir les effets nécessaires."] = "Track triggered effects and maintain required target effects.",
  ["Il faut surveiller le familier, son placement et son entretien."] = "Pet control, positioning and upkeep require attention.",
  ["Imposition des mains : le guide Vindicte propose de conserver le rang 1 pendant le leveling."] = "Lay on Hands: the Retribution guide suggests keeping rank 1 while leveling.",
  ["Inconvénients"] = "Drawbacks",
  ["Infliger des dégâts pour éliminer les ennemis."] = "Deal damage to defeat enemies.",
  ["Interface en français et en anglais, avec détection automatique de la langue du client et choix manuel dans les options."] = "French and English interface, with automatic game-client language detection and a manual option.",
  ["Jets de dés de groupe / raid"] = "Group / raid loot rolls",
  ["Jeu de base accessible et soutien important grâce aux totems."] = "Approachable basics and strong totem support.",
  ["Joueur contre joueur : combattre d'autres joueurs. C'est une activité, pas un rôle ; toutes les classes peuvent la pratiquer."] = "Player versus player: fighting other players. This is an activity, not a role; every class can take part.",
  ["LOW — rang inférieur au rang "] = "LOW — below learned rank ",
  ["La commande principale devient /sam ; retrouve les mêmes sous-commandes, dont /sam settings, /sam bookdebug et /sam conflicts."] = "The main command is now /sam, with the same subcommands including /sam settings, /sam bookdebug and /sam conflicts.",
  ["La discrétion aide surtout à préparer son ouverture face aux joueurs."] = "Stealth mainly helps prepare your opener against players.",
  ["La détection des grimoires possédés fonctionne aussi lorsque le familier concerné n’est pas actif."] = "Already-owned grimoire detection also works when the matching pet is inactive.",
  ["La détection et la protection prennent surtout leur valeur face aux autres joueurs."] = "Detection and protection are mainly valuable against other players.",
  ["La gestion de la mana et des incantations reste importante."] = "Mana and casting management remain important.",
  ["La gestion de l’énergie impose parfois des temps d’attente."] = "Energy management sometimes creates waiting periods.",
  ["La liste de classe de TrainerSpells peut afficher ECO / OPTIONAL et PVP / PVE PVP sur les sorts renseignés, selon tes réglages et la place disponible. Une case dédiée permet de masquer ces marqueurs dans Affichage."] = "The TrainerSpells class list can show ECO / OPTIONAL and PVP / PVE PVP on reviewed spells, according to settings and available space. A dedicated Display option hides them.",
  ["La liste est remplacée lorsqu'une nouvelle visite apporte des apprentissages. Les talents et recettes appris hors visite sont aussi suivis."] = "A new trainer visit replaces this list only when you learn something. Talent and recipe learning outside visits is also tracked.",
  ["La mana et les grosses pointes de dégâts restent des points de vigilance."] = "Mana and large damage spikes need attention.",
  ["La mana reste une contrainte à surveiller pendant la progression."] = "Mana requires attention while leveling.",
  ["La mobilité facilite le placement et la poursuite dans les deux activités."] = "Mobility helps positioning and pursuit in both activities.",
  ["La perte ou le mauvais placement du démon pénalise les dégâts."] = "Losing or poorly positioning the demon hurts damage.",
  ["La portée aide à se placer et à garder ses distances."] = "Range helps positioning and keeping your distance.",
  ["La protection contre les dissipations prend surtout de la valeur face aux joueurs."] = "Dispel protection is mainly valuable against players.",
  ["La reprise immédiate d’un ennemi peut demander une bonne préparation."] = "Immediately recovering an enemy's attention may require preparation.",
  ["La version tank de Farouche utilise surtout la forme d'ours pour encaisser les attaques et garder les ennemis concentrés sur elle. Ses choix de talents et son équipement doivent privilégier cette fonction. La possibilité de changer de forme offre des solutions de secours, mais passer en félin ou lancer un soin ne remplace pas la préparation nécessaire à chaque rôle."] = "Feral tank primarily uses Bear Form to take attacks and hold enemies' attention. Talents and equipment should prioritize tanking. Other forms provide emergency options, but shifting into a cat or casting a heal does not replace proper preparation for each role.",
  ["Langue"] = "Language",
  ["Langue de l’interface"] = "Interface language",
  ["Le badge RECENT est placé juste sous les icônes de sorts et de talents pour laisser leur image visible."] = "RECENT sits just below spell and talent icons to keep their artwork visible.",
  ["Le choix du démon et des bonus doit rester adapté au combat."] = "Choose the demon and bonuses to suit the encounter.",
  ["Le contrôle aléatoire peut créer une ouverture contre un joueur."] = "Random control can create an opening against a player.",
  ["Le contrôle supplémentaire aide surtout à empêcher un joueur de revenir au contact."] = "Extra control mainly helps keep a player from returning to melee range.",
  ["Le contrôle supplémentaire aide surtout à rester au contact d’un joueur."] = "Extra control mainly helps stay in melee range of a player.",
  ["Le contrôle supplémentaire peut gêner joueurs et ennemis sensibles."] = "Extra control can disrupt players and susceptible enemies.",
  ["Le fonctionnement caractéristique de l’arbre arrive progressivement pendant le leveling."] = "The tree's defining gameplay develops gradually while leveling.",
  ["Le guide donne explicitement cette plage; conserver le premier rang si utile."] = "The guide explicitly lists this rank range; keep the first rank if useful.",
  ["Le guide le cite comme facultatif mais souligne l'utilite des pistages en leveling."] = "The guide lists this as optional but notes that tracking is useful while leveling.",
  ["Le nombre de bénédictions, sceaux et protections demande de l’apprentissage."] = "The number of blessings, seals and protections takes time to learn.",
  ["Le nombre limité de grands bonus offensifs laisse moins de leviers pour une urgence."] = "Few major offensive boosts mean fewer emergency options.",
  ["Le placement des alliés et des totems compte pour profiter du soutien."] = "Ally and totem positioning affect support coverage.",
  ["Le placement et la portée des totems demandent un suivi régulier."] = "Totem placement and range require regular attention.",
  ["Le prochain palier de métier, comme Minage de compagnon, affiche NEXT au lieu de NOT NOW tant qu’il n’est pas encore apprenable."] = "The next profession tier, such as Journeyman Mining, shows NEXT instead of NOT NOW until learnable.",
  ["Le prochain palier d’apprentissage dispose aussi d’un fond jaune lorsque les fonds de statut sont activés."] = "The next learning tier also has a yellow background when status backgrounds are enabled.",
  ["Le rang 1 conserve une immobilisation de secours en Farouche. Les rangs suivants améliorent le contrôle."] = "Rank 1 keeps an emergency root for Feral. Later ranks improve control.",
  ["Le rang 1 de Bénédiction de sacrifice conserve l'usage de transfert de dégâts ; les rangs suivants restent utiles."] = "Rank 1 of Blessing of Sacrifice keeps the damage-transfer utility; later ranks remain useful.",
  ["Le rang 1 de Malédiction de témérité conserve l'effet empêchant la fuite, sans rechercher son effet offensif maximal."] = "Rank 1 of Curse of Recklessness prevents fleeing without aiming for its maximum offensive effect.",
  ["Le rang 1 suffit pour l'usage conseillé pendant le leveling selon ton rôle. Le sort lui-même reste utile ; les rangs supérieurs peuvent améliorer ses effets."] = "Rank 1 suffices for the recommended leveling use according to your role. The spell itself remains useful; higher ranks may improve its effects.",
  ["Le rôle DPS ne permet pas de remplacer automatiquement un tank ou un soigneur spécialisé."] = "Being DPS does not automatically replace a dedicated tank or healer.",
  ["Le rôle de la spécialisation affichée apparaît à gauche du titre du grimoire, avec les icônes et les explications de l’arbre de talents."] = "The active specialization's role appears beside the spellbook title, with the same icons and explanations as the talent trees.",
  ["Le soutien au groupe repose surtout sur les dégâts, interruptions et outils du voleur."] = "Group support mainly comes from damage, interrupts and rogue tools.",
  ["Les armes et les caractéristiques de l’équipement ont une grande importance."] = "Weapons and equipment stats matter greatly.",
  ["Les attaques manquées peuvent provoquer un manque de rage."] = "Missed attacks can cause rage shortages.",
  ["Les attaques à distance restent gênées si l’ennemi s’approche trop."] = "Ranged attacks are hindered when enemies get too close.",
  ["Les badges du grimoire disparaissent lorsque l’on ouvre un onglet d’un autre addon, puis reviennent avec la liste des sorts."] = "Spellbook badges hide on another addon's tab and return with the spell list.",
  ["Les boutons de réinitialisation ouvrent correctement leur confirmation, puis la proposition de rechargement."] = "Reset buttons correctly open confirmation followed by the reload prompt.",
  ["Les cases d’icônes par zone deviennent non modifiables lorsque les icônes sont désactivées globalement, sans perdre leurs valeurs."] = "Per-zone icon options become unavailable when icons are disabled globally, without losing their values.",
  ["Les choix centrés sur le personnage peuvent réduire l’aide apportée par le familier."] = "Character-focused choices may reduce the pet's contribution.",
  ["Les conseils OPTIONAL distinguent un sort facultatif des seuls rangs supplémentaires que l’on peut reporter."] = "OPTIONAL advice distinguishes an optional spell from deferrable extra ranks.",
  ["Les critiques créent des enchaînements offensifs dynamiques."] = "Critical hits create dynamic offensive sequences.",
  ["Les drains apportent de la récupération de vie et une bonne autonomie."] = "Drains provide health recovery and self-sufficiency.",
  ["Les effets essentiels doivent être renouvelés sans gaspiller les points de combo."] = "Refresh key effects without wasting combo points.",
  ["Les effets répartis sur plusieurs cibles sont moins renforcés qu’en Affliction."] = "Spread-out damage effects receive less support than in Affliction.",
  ["Les enchaînements offensifs peuvent rapidement consommer la mana."] = "Offensive sequences can quickly consume mana.",
  ["Les ennemis insensibles aux saignements contrarient fortement son fonctionnement."] = "Bleed-immune enemies strongly disrupt its gameplay.",
  ["Les grimoires déjà possédés portent la mention Already in your Bag."] = "Already-owned grimoires display Already in your Bag.",
  ["Les immobilisations imprévisibles gênent surtout les déplacements des joueurs."] = "Unpredictable roots mainly disrupt player movement.",
  ["Les incantations et la distance minimale rendent le placement important."] = "Cast times and minimum range make positioning important.",
  ["Les indications de rôle des arbres de talents disposent d’un cadre doré, contrôlé par l’option des contours."] = "Talent-tree role labels have a gold frame controlled by the outline setting.",
  ["Les livres déjà possédés sont signalés chez le marchand. Le stockage en banque correspond aux dernières informations observées."] = "Books you already own are marked at merchants. Bank storage reflects the last observed contents.",
  ["Les marqueurs de la liste TrainerSpells restent associés aux bons sorts pendant le défilement."] = "TrainerSpells list markers stay attached to the correct spells while scrolling.",
  ["Les marqueurs suivent les lignes remplacées par TrainerSpells ; la coloration de ses textes reste sous son contrôle."] = "Markers follow rows replaced by TrainerSpells; its text colors remain under its control.",
  ["Les pièges peuvent retenir des joueurs ou des ennemis en PvE."] = "Traps can hold players or enemies in PvE.",
  ["Les priorités entre les sorts demandent davantage d’apprentissage."] = "Spell priorities take more practice to learn.",
  ["Les rangs non appris ou réservés à un niveau futur ne provoquent plus de marqueur LOW incorrect."] = "Unlearned or future-level ranks no longer cause incorrect LOW markers.",
  ["Les rangs très anciens peuvent moins profiter des bonus de dégâts/soins. Les limites de cible et les pénalités de déclenchement dépendent du sort ; ce n'est pas une pénalité générale au toucher."] = "Very old ranks may benefit less from damage/healing bonuses. Target limits and effect penalties depend on the spell; lower ranks do not have a universal hit penalty.",
  ["Les rapports peuvent être copiés depuis une fenêtre d’export dédiée."] = "Reports can be copied from a dedicated export window.",
  ["Les repères PVP / PVE PVP des talents sont placés sous les icônes et ajustés à leur largeur pour laisser les points dépensés visibles."] = "Talent PVP / PVE PVP markers sit below icons and fit their width, keeping spent points visible.",
  ["Les repères PVP / PVE PVP peuvent être masqués dans Affichage et suivent les cases du maître de classe et de l’arbre de talents."] = "PVP / PVE PVP can be hidden in Display and follow trainer and talent-tree category settings.",
  ["Les résistances au givre et les déclenchements manqués limitent son efficacité."] = "Frost resistance and missed proc opportunities limit effectiveness.",
  ["Les saignements continuent d’agir lorsque le voleur doit momentanément s’éloigner."] = "Bleeds keep dealing damage when you briefly move away.",
  ["Les soins directs nécessitent de quitter la Forme d’ombre."] = "Direct healing requires leaving Shadowform.",
  ["Les soins sur la durée demandent de l’anticipation et une bonne lecture du combat."] = "Healing over time requires anticipation and awareness of the fight.",
  ["Les soins sur plusieurs alliés sont moins développés que ses outils ciblés."] = "Multi-ally healing is less developed than targeted tools.",
  ["Les sorts affichés comme Invocation, dont Œil de Kilrogg, peuvent recevoir les conseils OPTIONAL prévus."] = "Spells labeled Summon, including Eye of Kilrogg, can receive their intended OPTIONAL advice.",
  ["Les talents renforcent aussi les dégâts de feu contre des groupes."] = "Talents also improve Fire damage against groups.",
  ["Les trois arbres permettent de jouer DPS en groupe. Destruction privilégie les dégâts directs ; Affliction et Démonologie restent de bons choix si tu continues aussi les quêtes en solo."] = "All three trees can deal damage in groups. Destruction favors direct damage; Affliction and Demonology remain good choices if you also continue solo quests.",
  ["Les trois voies peuvent progresser en groupe. Choisis celle dont tu préfères le rythme et apprends à contrôler le familier et les distances."] = "All three paths can level in groups. Choose the rhythm you enjoy and learn to control your pet and distance.",
  ["Leveling Farouche; conserver le controle au rang 1."] = "Feral leveling; keep rank 1 for control.",
  ["Leveling Vindicte du guide, pas tank ni soin; rangs superieurs peuvent avoir des benefices."] = "The guide's Retribution leveling path, not tanking or healing; higher ranks may have benefits.",
  ["Leveling solo Vindicte; utilitaire ou contenu morts-vivants/PvP a prendre en compte."] = "Solo Retribution leveling; consider utility and undead/PvP content.",
  ["Liste TrainerSpells"] = "TrainerSpells list",
  ["Liste optionnelle du guide; protections et chute lente utiles selon zone; Scorch a conserver si build/debuff le demande."] = "Listed as optional by the guide; wards and Slow Fall depend on the area. Keep Scorch if your build or debuff needs it.",
  ["Livre apprenable : contour jaune et marqueur + lorsque les informations du familier sont disponibles."] = "Learnable book: yellow outline and + marker when pet information is available.",
  ["Livre déjà appris : surimpression assombrie et indication du démon concerné."] = "Learned book: dark overlay and the matching demon marker.",
  ["Livres de démons : grimoires appris, apprenables et déjà possédés. Invoque chaque démon pour enregistrer ses sorts."] = "Demon books: learned, learnable and already-owned grimoires. Summon each demon to record its spells.",
  ["Livres du familier (/sam petdebug)"] = "Pet books (/sam petdebug)",
  ["L’affichage des recettes connues et les marqueurs des jets de dés peuvent être activés ou masqués dans Affichage."] = "Learned-recipe and loot-roll markers can be enabled or hidden in Display.",
  ["L’arbre se construit progressivement avant de disposer de ses interactions importantes."] = "Important talent interactions take time to develop.",
  ["L’efficacité offensive baisse lorsqu’il n’est pas activement en train d’encaisser."] = "Offensive effectiveness falls when you are not actively taking attacks.",
  ["L’indication de rôle du grimoire reste reconnue lorsque DarkMode recolore le titre de spécialisation ; les infobulles d’onglets acceptent aussi ces titres colorés."] = "Spellbook role labels remain recognized when DarkMode recolors specialization titles; school tooltips also accept colored titles.",
  ["L’onglet Apprentissages récents regroupe ces apprentissages. Le marqueur RECENT et son affichage dans les métiers disposent de réglages dans Affichage."] = "Recent learning lists these entries. RECENT and its profession display have their own settings in Display.",
  ["L’énergie, les points de combo et les changements de forme demandent de l’attention."] = "Energy, combo points and shapeshifting require attention.",
  ["L’équipement et la gestion d’une réserve de mana limitée ont un impact important."] = "Equipment and a limited mana pool have a significant impact.",
  ["L’équipement idéal pour tanker limite les performances dans les autres rôles."] = "Ideal tanking gear limits performance in other roles.",
  ["Marchand"] = "Merchant",
  ["Marquer le rang 1 des sorts retenus pour tes rôles et spécialisations. Les conseils spécifiques attendent le choix de la spécialisation."] = "Mark rank 1 of reviewed spells for your roles and specializations. Specialization-specific advice waits for your specialization choice.",
  ["Masquer le bouton de minicarte dans Affichage sans retirer le lanceur des panneaux DataBroker."] = "Hide the minimap button in Display without removing the DataBroker launcher.",
  ["Maître de classe"] = "Class trainer",
  ["Maître de classe (/sam debug)"] = "Class trainer (/sam debug)",
  ["Maîtres : NEW + = apprenable, coche verte = appris, NEXT = prochain palier, NOT NOW = indisponible."] = "Trainers: NEW + = learnable, green check = learned, NEXT = next tier, NOT NOW = unavailable.",
  ["Maîtrise des bêtes"] = "Beast Mastery",
  ["Maîtrise des bêtes est un choix accessible pour débuter : le familier encaisse et apporte une part importante des dégâts. Précision et Survie sont aussi des parcours viables, selon ton style de jeu."] = "Beast Mastery is approachable for beginners: the pet takes attacks and supplies much of your damage. Marksmanship and Survival are also viable paths, depending on your preferences.",
  ["Maîtrise des bêtes renforce la coopération entre le chasseur et son familier, qui prend une part importante dans les combats. Le chasseur utilise ses tirs, entretient les effets apportés par ses talents et dirige son compagnon. Le contrôle des distances, des pièges et du familier garde une grande importance même si les premières étapes sont assez accessibles."] = "Beast Mastery strengthens cooperation between hunter and pet, which contributes substantially in combat. Use shots, maintain talent effects and direct your companion. Distance, traps and pet control remain important even though the early basics are approachable.",
  ["Minicarte : clic gauche pour les options, clic droit pour ce résumé."] = "Minimap: left-click for options, right-click for this summary.",
  ["Mobilité et contrôle peuvent aider en PvP comme sur les ennemis accessibles."] = "Mobility and control can help in PvP and against susceptible enemies.",
  ["Mobilité et interruption utiles en tank, en solo et contre les joueurs."] = "Mobility and interrupts useful for tanking, solo play and fighting players.",
  ["Mobilité et possibilités de dégâts contre plusieurs ennemis."] = "Mobility and damage against multiple enemies.",
  ["Mobilité utile pour le placement en PvE et pour poursuivre ou fuir en PvP."] = "Mobility helps PvE positioning and PvP pursuit or escape.",
  ["Moins efficace quand les ennemis meurent avant que ses effets aient agi."] = "Less effective when enemies die before effects deal their damage.",
  ["Moments de dégâts renforcés et fonctionnement de base assez direct."] = "Strong damage windows and straightforward basics.",
  ["Métiers"] = "Professions",
  ["Métiers : NEXT indique le prochain palier d'apprentissage."] = "Professions: NEXT marks the next training step.",
  ["Ne peut pas retirer tous les types d’effets néfastes, notamment magiques ou de maladie."] = "Cannot remove every harmful effect type, notably magic and disease.",
  ["Niveau requis : "] = "Required level: ",
  ["Nombreux contrôles et protections pour survivre."] = "Plenty of control and protection for survival.",
  ["OPTIONAL — achat facultatif pendant le leveling selon tes rôles et spécialisations."] = "OPTIONAL — a leveling purchase that can wait for your roles and specializations.",
  ["OPTIONAL — l'achat de ce rang supplémentaire peut attendre pendant le leveling."] = "OPTIONAL — buying this extra rank can wait while leveling.",
  ["OPTIONAL — seuls les rangs supplémentaires sont facultatifs."] = "OPTIONAL — only extra ranks are optional.",
  ["Ombre"] = "Shadow",
  ["Ombre convient si tu privilégies les dégâts en solo et l'accès à la Forme d'ombre. Discipline est une alternative rassurante pour débuter, avec de la survie et de bons soins ; la baguette reste importante aux premiers niveaux."] = "Shadow suits solo damage and access to Shadowform. Discipline is a reassuring beginner alternative with survival and healing; wands remain important at early levels.",
  ["Ombre transforme le prêtre en lanceur de sorts offensif : il maintient ses effets sur la cible et les complète avec ses attaques d'ombre. Son identité se développe progressivement avec les talents, en particulier avec la Forme d'ombre. Il apporte aussi du soutien indirect au groupe, mais ne joue pas comme un soigneur spécialisé lorsqu'il reste dans cette forme."] = "Shadow turns the priest into an offensive caster, maintaining effects and supplementing them with Shadow attacks. Its identity develops through talents, especially Shadowform. It also provides indirect group support but does not act as a dedicated healer while staying in that form.",
  ["Option PvP; ne pas copier cette regle en Demonologie avec Demonic Brand."] = "PvP option; do not apply this advice to Demonology with Demonic Brand.",
  ["Option offensive utilisée en Vindicte dans les deux activités."] = "An offensive Retribution option used in both activities.",
  ["Options : /sam settings. Résumé : /sam ou /skillsandmore. Tous les rapports restent accessibles par les commandes indiquées sur les boutons."] = "Options: /sam settings. Summary: /sam or /skillsandmore. All reports remain available through the commands shown on their buttons.",
  ["Outil de poursuite particulièrement intéressant contre les joueurs en monde ouvert."] = "A pursuit tool particularly useful against players in the open world.",
  ["Outil surtout utile pour gêner les joueurs adverses."] = "A tool mainly useful for disrupting enemy players.",
  ["Outils de camouflage, de survie et de contrôle propres au voleur."] = "Rogue stealth, survival and control tools.",
  ["Outils du chasseur pour ralentir, piéger et maintenir la distance."] = "Hunter tools for slowing, trapping and keeping enemies away.",
  ["Outils intéressants contre plusieurs ennemis et contre les dégâts magiques."] = "Useful tools against multiple enemies and magic damage.",
  ["Outils intéressants contre plusieurs ennemis proches et pour contrôler une cible."] = "Useful tools against nearby groups and for controlling a target.",
  ["Outils intéressants pour économiser la mana et gérer les groupes d’ennemis."] = "Useful mana-saving and enemy-group management tools.",
  ["Outils précieux de soutien, de récupération de mana et de résurrection en combat."] = "Valuable support, mana recovery and combat resurrection tools.",
  ["Outils solides de réduction des dégâts et de reprise rapide d’un ennemi."] = "Strong damage reduction and quick enemy-recovery tools.",
  ["Ouverture possible; filler du parcours repose sur Drain Life/Searing Pain; pas regle Destruction."] = "Can be used as an opener; this path uses Drain Life/Searing Pain as filler. Not a Destruction rule.",
  ["Ouvre le grimoire du joueur avant ce rapport pour relever les sorts visibles et les marqueurs."] = "Open your spellbook before this report to inspect visible spells and markers.",
  ["Ouvrir des rapports copiables avec /sak debug, /sak pet et /sak petdebug."] = "Open copyable reports with /sak debug, /sak pet and /sak petdebug.",
  ["Ouvrir le résumé (/sam)"] = "Open summary (/sam)",
  ["Ouvrir les options avec un clic gauche, le résumé avec un clic droit. Masquer ce bouton conserve le lanceur disponible dans les panneaux DataBroker comme HidingBar et Titan Panel."] = "Left-click for options, right-click for the summary. Hiding this button keeps the launcher available in DataBroker displays such as HidingBar and Titan Panel.",
  ["Ouvrir les options par clic gauche sur le bouton de minicarte, ou le résumé par clic droit. Le lanceur est disponible pour les panneaux DataBroker, notamment HidingBar et Titan Panel."] = "Left-click the minimap button for options, right-click for the summary. The launcher is available in DataBroker displays, including HidingBar and Titan Panel.",
  ["PVP : principalement intéressant contre les joueurs, sans exclure un usage PvE. PVE PVP : utile dans les deux activités. Ces repères apparaissent sur les talents vérifiés et les sorts apprenables du maître de classe. Survole un repère pour lire son explication. Ils ne rendent aucun achat obligatoire ou facultatif ; les entrées non vérifiées restent sans marqueur."] = "PVP: mainly useful against players, without excluding PvE. PVE PVP: useful in both activities. Markers appear on reviewed talents and learnable trainer spells. Hover for details. They do not make purchases mandatory or optional; unreviewed entries stay unmarked.",
  ["Palette de soins variée, adaptée à de nombreuses situations de groupe."] = "Varied healing suited to many group situations.",
  ["Parcours Fureur du guide; ne pas appliquer a Armes utilisant Improved Slam."] = "The guide's Fury path; not Arms using Improved Slam.",
  ["Parcours Protection bouclier; pas regle DPS."] = "Shield-based Protection path; not a DPS rule.",
  ["Permet de retrouver plus souvent son contrôle de proximité."] = "Makes your close-range control available more often.",
  ["Permet d’écarter temporairement une cible sensible en PvE ou PvP."] = "Temporarily removes a susceptible target from combat in PvE or PvP.",
  ["Peu de grandes capacités offensives à synchroniser."] = "Few major offensive cooldowns to synchronize.",
  ["Peu de récupération de vie pendant le combat."] = "Limited health recovery during combat.",
  ["Pistage utile en quetes; Flare PvP; Monkey survie/melee, notamment Survie. Aucun classement general sur la seule specialisation."] = "Tracking helps with quests; Flare is useful in PvP; Monkey helps melee survival, especially Survival. No blanket rule based solely on specialization.",
  ["Pistage utile en quetes; report seulement si le joueur ne l'utilise pas."] = "Tracking helps with quests; delay only if you do not use it.",
  ["Plage explicite du guide; usages de posture/build a confirmer."] = "Explicit guide range; confirm stance and build requirements.",
  ["Plus haut rang appris, même s'il est seul : dégâts, soins et effets de ce rang. Ne garantit pas de toucher ni d'être le rang maximal du jeu."] = "Highest learned rank, even alone: damage, healing and effects of this rank. Does not guarantee a hit or the maximum rank in the game.",
  ["Plus haut rang appris, même seul.\nDégâts, soins et effets de ce rang."] = "Highest learned rank, even alone.\nDamage, healing and effects of this rank.",
  ["Plus tard"] = "Later",
  ["Plusieurs effets et utilisations du camouflage sont à gérer en plus de l’énergie."] = "Manage several effects and stealth uses alongside energy.",
  ["Plusieurs protections et outils de secours pour aider les alliés."] = "Several protections and emergency tools for allies.",
  ["Polyvalence des formes et capacité à s’adapter aux imprévus."] = "Flexible forms help adapt to unexpected situations.",
  ["Possibilité d’aider ponctuellement avec des soins ou la forme d’ours."] = "Can occasionally help with healing or Bear Form.",
  ["Pour empecher la fuite ou retirer l'effet de Fear; premier achat lui-meme situationnel."] = "To prevent escape or remove Fear; the first purchase itself is situational.",
  ["Pour generation de fragments en fin de combat pendant leveling; reevaluer usages de degats."] = "For generating shards near the end of leveling fights; reassess when using it for damage.",
  ["Premier rang utile; rangs suivants reportables, pas identiques en duree/cibles."] = "The first rank is useful; later purchases can wait, but duration and eligible targets may differ.",
  ["Première utilisation : sorts déjà connus du palier de niveau "] = "First use: known spells from level tier ",
  ["Principalement intéressant contre les joueurs. Cela n’exclut pas un usage PvE."] = "Mainly useful against players. This does not exclude PvE use.",
  ["Prolonge un contrôle pour gagner du temps sur une cible sensible."] = "Extends control to gain time against a susceptible target.",
  ["Protection défensive utile sur les alliés exposés aux attaques."] = "Defensive protection for allies exposed to attacks.",
  ["Protection d’urgence utile face aux mécaniques PvE et aux joueurs."] = "Emergency protection useful against PvE mechanics and players.",
  ["Protection liée au démon, utile sous la pression d’ennemis ou de joueurs."] = "Demon-related protection useful under pressure from enemies or players.",
  ["Protection lorsque l’on subit des attaques au corps à corps."] = "Protection while taking melee attacks.",
  ["Protection pour tanker les donjons, Sacré pour soigner si tu progresses surtout accompagné. Vindicte convient si tu veux conserver un rôle de dégâts."] = "Protection for dungeon tanking, Holy for healing if you mainly level with others. Retribution fits a damage role.",
  ["Protection principalement intéressante contre les contrôles et dissipations des joueurs."] = "Protection mainly useful against player control and dispels.",
  ["Protection si tu progresses surtout en tankant les donjons. Armes ou Fureur conviennent pour jouer DPS, notamment avec un soigneur pour réduire les pauses."] = "Protection if you mainly level by tanking dungeons. Arms or Fury suit DPS, especially with a healer to reduce downtime.",
  ["Protection utilise surtout une arme et un bouclier pour encaisser, réduire les dégâts subis et garder l'attention des ennemis. Le guerrier construit sa rage pendant le combat et la dépense pour maintenir sa menace et ses protections. Son rôle consiste aussi à placer les adversaires et à affaiblir leurs attaques pour sécuriser le groupe."] = "Protection mainly uses a weapon and shield to withstand attacks, reduce damage and hold enemies' attention. Build rage in combat and spend it on threat and protection. Position enemies and weaken their attacks to keep the group safe.",
  ["Protection utilise un bouclier, des effets sacrés et ses auras pour encaisser et attirer l'attention des ennemis. Il est particulièrement à l'aise lorsque plusieurs adversaires restent regroupés autour de ses zones offensives. Contrairement aux tanks qui utilisent la rage, il doit aussi gérer sa mana pour continuer à lancer ses capacités pendant toute la rencontre."] = "Protection uses a shield, Holy effects and auras to withstand attacks and hold enemies. It is especially comfortable when several opponents stay within its offensive areas. Unlike rage tanks, it must manage mana to keep using abilities throughout the encounter.",
  ["Protections et soutien du paladin utiles au groupe."] = "Paladin protections and support benefit the group.",
  ["Précision"] = "Marksmanship",
  ["Précision concentre une grande partie de son jeu sur les tirs du chasseur, avec des attaques puissantes qui demandent du temps pour être préparées. Le joueur doit bien choisir sa position et maintenir une distance adaptée avec les ennemis. Selon les talents retenus dans Forever, la place du familier peut changer : il ne faut pas supposer le fonctionnement d'une autre version du jeu."] = "Marksmanship focuses on powerful hunter shots that take time to prepare. Position carefully and maintain suitable distance. Forever talent choices can change the pet's role; do not assume it works like another game version.",
  ["Préparer un signalement"] = "Prepare a bug report",
  ["Prêtre"] = "Priest",
  ["PvP : joueur contre joueur. Toutes les classes peuvent pratiquer cette activité."] = "PvP: player versus player. Every class can take part in this activity.",
  ["RECENT : derniers sorts, talents et recettes appris, conservés après rechargement. Consulte Apprentissages récents dans les options."] = "RECENT: latest learned spells, talents and recipes, saved after reloads. See Recent learning in the options.",
  ["RECENT repère les derniers sorts, talents et recettes appris dans les vues reconnues du grimoire, des talents, des métiers et de TrainerSpells. La liste reste enregistrée après rechargement ; une visite sans apprentissage conserve la précédente."] = "RECENT marks the latest learned spells, talents and recipes in supported spellbook, talent, profession and TrainerSpells views. The list survives reloads; an empty trainer visit keeps it.",
  ["RECENT — derniers apprentissages"] = "RECENT — latest learning",
  ["RECENT — récemment appris"] = "RECENT — recently learned",
  ["Ralentir davantage aide à tenir à distance joueurs et ennemis."] = "Stronger slows help keep players and enemies at a distance.",
  ["Ralentissement de proximité pour gérer plusieurs poursuivants."] = "A nearby slow for managing multiple pursuers.",
  ["Ralentit une cible pour contrôler la distance, y compris en solo PvE."] = "Slows a target to control distance, including solo PvE.",
  ["Rang 1 permet un usage de base; les rangs superieurs restent utiles, notamment cibles/duree/PvP."] = "Rank 1 enables basic use; higher ranks remain useful, especially for target limits, duration and PvP.",
  ["Rang 1 pour usage anti-controle PvP; peut etre reporte entierement en solo."] = "Rank 1 for countering control in PvP; the entire purchase can wait in solo play.",
  ["Rang appris : "] = "Learned rank: ",
  ["Rang inférieur appris : dégâts, soins ou effets peuvent être moins efficaces. Certains contrôles ont une limite de niveau. Pas d'économie de mana garantie."] = "An older learned rank: damage, healing or effects may be weaker. Some control spells have target-level limits. No guaranteed mana savings.",
  ["Rang suffisant pour pex (rôle).\nÉconomie d'or, pas de mana garantie."] = "Sufficient leveling rank (role).\nSaves gold, not guaranteed mana.",
  ["Rang suffisant pour pex selon ton rôle. Économie de pièces d'or en reportant les achats de rangs, pas d'économie de mana garantie."] = "Sufficient rank for the recommended leveling use. Saves training gold by delaying rank purchases, not guaranteed mana.",
  ["Rangs supplémentaires facultatifs pendant le leveling. "] = "Extra ranks are optional while leveling. ",
  ["Rapports"] = "Reports",
  ["Recettes"] = "Recipes",
  ["Recevoir une présélection selon ses talents dépensés, ou une spécialisation conseillée pour le leveling avant le niveau 10 et sans arbre dominant."] = "Receive a suggestion based on spent talent points, or a leveling specialization before level 10 and when no tree dominates.",
  ["Recharger l'interface"] = "Reload interface",
  ["Recharger l'interface pour appliquer la langue choisie ?"] = "Reload the interface to apply the selected language?",
  ["Refresh"] = "Refresh",
  ["Relancer le premier lancement"] = "Restart first use",
  ["Relire les sorts appris et actualiser les fenêtres ouvertes."] = "Read learned spells again and refresh open windows.",
  ["Renforce le contrôle pour garder les ennemis à distance."] = "Improves control to keep enemies at a distance.",
  ["Renforce les attaques concernées en PvE comme en PvP."] = "Improves the affected attacks in PvE and PvP.",
  ["Renforce les attaques concernées, selon le jeu choisi."] = "Improves the affected attacks, depending on your play style.",
  ["Renforce les contrôles, utiles aussi pour gérer un ennemi en PvE."] = "Improves control, also useful for managing an enemy in PvE.",
  ["Renforce les critiques des attaques concernées dans les deux activités."] = "Improves critical hits of affected attacks in both activities.",
  ["Renforce les critiques offensifs dans les deux activités."] = "Improves offensive critical hits in both activities.",
  ["Renforce les dégâts lorsque les conditions du talent sont réunies."] = "Improves damage when the talent's conditions are met.",
  ["Renforce les outils de protection et de liberté pour aider un allié."] = "Improves protection and freedom tools to help an ally.",
  ["Renforce les soins de Rétablissement dans les deux activités."] = "Improves Regrowth healing in both activities.",
  ["Renforce les totems défensifs, utiles contre les sorts et les attaques."] = "Improves defensive totems, useful against spells and attacks.",
  ["Renforce l’offensive du familier dans les deux activités."] = "Improves pet offense in both activities.",
  ["Renforce un moment de soin ou d’offensive selon la spécialisation."] = "Improves a healing or offensive window, depending on specialization.",
  ["Renforce une attaque décisive dans les deux activités."] = "Improves a decisive attack in both activities.",
  ["Renfort offensif utilisable dans les combats PvE et PvP."] = "An offensive boost usable in PvE and PvP fights.",
  ["Renfort offensif utilisable dans les deux activités."] = "An offensive boost usable in both activities.",
  ["Renfort pour un lanceur de sorts, en groupe PvE ou PvP."] = "A caster boost for PvE or PvP groups.",
  ["Report possible en leveling Ombre; capacite sur cibles de haut niveau, menace, soin/groupe a verifier. Pas equivalence de tous les rangs."] = "Can wait while leveling Shadow; check high-level targets, threat and healing/group use. Ranks are not all equivalent.",
  ["Report propose par le guide de leveling; Rain of Fire/Hellfire exige validation securite et AoE avant recommandation automatique."] = "The leveling guide suggests delaying it; assess safety and AoE needs before skipping Rain of Fire or Hellfire.",
  ["Reporter cet achat permet d'économiser de l'or pendant le leveling."] = "Delaying this purchase saves training gold while leveling.",
  ["Repère d’usage, pas une obligation de talent ou d’achat."] = "Usage advice, not a mandatory talent or purchase.",
  ["Repérer BUY NEW RANK lorsqu’un rang supérieur accessible reste à apprendre, hors achats classés ECO ou OPTIONAL."] = "Identify BUY NEW RANK when an accessible higher rank remains to learn, outside ECO / OPTIONAL purchases.",
  ["Repérer dans le grimoire BEST (plus haut rang appris), LOW (ancien rang appris), ECO (rang suffisant pour l’usage conseillé) et OPTIONAL (achat facultatif selon ses rôles)."] = "Identify BEST (highest learned rank), LOW (older learned rank), ECO (sufficient recommended rank) and OPTIONAL (purchase can wait for your roles) in the spellbook.",
  ["Repérer les exemplaires déjà possédés grâce aux dernières positions connues dans les sacs, la banque et la banque de guilde."] = "Spot already-owned copies from their last observed locations in bags, the bank and guild bank.",
  ["Repérer les grimoires déjà appris et apprenables chez les marchands avec une icône de démon et des marqueurs de livre."] = "Spot learned and learnable grimoires at merchants with demon icons and book markers.",
  ["Repérer les sorts déjà connus et apprenables chez le maître de classe grâce à des marqueurs sur les icônes."] = "Spot known and learnable class-trainer spells through icon markers.",
  ["Resistances selon contenu; aucune extrapolation a une ligne vide du tableau."] = "Resistance value depends on content; do not extend the advice to unspecified entries.",
  ["Resistances selon zone/groupe; Frostbrand selon PvP; pas de skip si besoin specifique."] = "Resistance depends on the area/group; Frostbrand may matter in PvP. Do not skip a specific need.",
  ["Restauration"] = "Restoration",
  ["Restauration s'appuie beaucoup sur des soins qui continuent d'agir pendant plusieurs secondes. Le joueur anticipe les dégâts, répartit ses effets sur les bons alliés et les complète avec des soins directs lorsque la situation l'exige. Sa force vient du suivi des cibles et de la préparation plutôt que d'une réaction identique à chaque perte de vie."] = "Restoration relies heavily on healing effects that last several seconds. Anticipate damage, apply effects to the right allies and supplement them with direct heals when needed. Success comes from preparation and tracking targets rather than reacting identically to every health loss.",
  ["Restauration si tu progresses régulièrement en soignant un groupe. Amélioration ou Élémentaire conviennent pour jouer DPS tout en apportant les totems."] = "Restoration if you regularly level by healing a group. Enhancement or Elemental suit a DPS role while contributing totems.",
  ["Restauration soigne avec un mélange de soins directs, d'effets sur la durée et de soins qui rebondissent entre les alliés. Les totems complètent ce travail en apportant des bonus et du soutien. Forever enrichit cette base sans en changer l'idée principale : choisir le bon soin pour les blessés et maintenir ses outils de groupe en bonne position."] = "Restoration mixes direct heals, healing over time and heals that bounce between allies. Totems add buffs and support. Forever expands these tools without changing the main idea: choose the right heal and keep group tools positioned well.",
  ["Restauration soin; acheter les degats si leveling solo. Le guide cite des rangs tardifs, pas une preuve que le rang 1 suffit."] = "Restoration healing; buy damage spells for solo leveling. The guide discusses later ranks, not proof that rank 1 suffices.",
  ["Retenir des ennemis peut protéger le groupe ou empêcher un joueur de poursuivre."] = "Holding enemies can protect the group or stop a player pursuing you.",
  ["Retrouver certains outils peut aider à survivre ou relancer une offensive."] = "Restoring certain tools can help survival or start another offensive.",
  ["Retrouver dans les infobulles les indications d’apprentissage et de niveau de déblocage du familier."] = "Read learning and pet-unlock level information in tooltips.",
  ["Retrouver les conseils ECO et OPTIONAL chez le maître de classe et dans les infobulles de sorts reconnues, y compris hors du grimoire."] = "Find ECO and OPTIONAL advice at class trainers and in recognized spell tooltips, including outside the spellbook.",
  ["Retrouver sa peur plus souvent aide surtout à se dégager des joueurs."] = "Having Fear available more often mainly helps escape players.",
  ["Retrouver son étourdissement plus souvent aide à gérer une menace."] = "Having your stun available more often helps manage a threat.",
  ["Rythme actif, avec des dégâts réguliers et de nombreux contrôles."] = "Active gameplay with steady damage and plenty of control.",
  ["Réactiver les catégories d'affichage et les conseils. Les rôles sont reproposés selon tes talents actuels ou le leveling conseillé."] = "Re-enable display categories and advice. Roles are suggested again from your current talents or the leveling recommendation.",
  ["Réactivité pour un soin ou un sort urgent dans les deux activités."] = "A quick response for an urgent heal or spell in both activities.",
  ["Récupération de vie limitée et gestion des ressources nécessaire sur la durée."] = "Limited health recovery and ongoing resource management.",
  ["Réinitialisation"] = "Reset",
  ["Réinitialisation effectuée. Recharger l'interface maintenant ?\nAvec « Plus tard », tes choix sont conservés et tu peux utiliser /reload quand tu le souhaites."] = "Settings reset. Reload the interface now?\nWith Later, your choices are saved and you can use /reload whenever you wish.",
  ["Réponse immédiate pour soigner ou infliger des dégâts."] = "An immediate response for healing or damage.",
  ["Résister aux contrôles est surtout utile face aux joueurs."] = "Resisting control is mainly useful against players.",
  ["Résurrection : le rang 1 permet de ressusciter ; les rangs suivants rendent davantage de vie et de mana."] = "Resurrection: rank 1 revives allies; later ranks restore more health and mana.",
  ["Rétablir l'affichage, les conseils et les choix de rôle par défaut pour ce personnage ?"] = "Restore default display, advice and role choices for this character?",
  ["Rétablir les options ou relancer le premier lancement depuis Réinitialisation, avec confirmation puis Recharger l’interface / Plus tard."] = "Restore defaults or restart first use from Reset, with confirmation and Reload interface / Later.",
  ["Rétablir les options par défaut"] = "Restore default options",
  ["Rétablis les réglages ou teste à nouveau le premier lancement. Les sorts du familier et les livres enregistrés sont conservés."] = "Restore settings or test the first-use window again. Saved pet spells and books are kept.",
  ["Rôles et spécialisations"] = "Roles and specializations",
  ["Rôles et talents : résumés des spécialisations, recommandation LEVELING et repères PVP / PVE PVP sur les entrées renseignées."] = "Roles and talents: specialization summaries, LEVELING recommendations and PVP / PVE PVP markers on reviewed entries.",
  ["Sacre soin; tanking hybride, generation de menace et controle changent les priorites."] = "Holy healing; hybrid tanking, threat generation and control change the priorities.",
  ["Sacré"] = "Holy",
  ["Sacré privilégie les soins tout en conservant les protections, bénédictions et auras du paladin. Forever ajoute des interactions permettant de mieux répondre aux dégâts de groupe, en plus des soins ciblés. Le fonctionnement de base est accessible, mais il faut progressivement apprendre à choisir les bons outils de soutien et à gérer ses sceaux."] = "Holy focuses on healing while retaining paladin protections, blessings and auras. Forever adds interactions for group damage as well as targeted heals. The basics are approachable, but choosing support tools and managing seals takes practice.",
  ["Sacré propose une large palette de soins pour répondre aux dégâts subis par un allié ou par le groupe. Forever ajoute notamment des outils qui soignent plusieurs personnes ou rebondissent entre les alliés, tout en conservant les soins directs classiques. Le joueur adapte son sort à l'urgence, au nombre de blessés et à sa réserve de mana."] = "Holy offers varied heals for damage to an ally or the group. Forever adds multi-target and bouncing heals alongside traditional direct healing. Choose spells according to urgency, the number of injured allies and available mana.",
  ["Sacs et banques"] = "Bags and banks",
  ["Select All"] = "Select All",
  ["Seulement si aucun tanking prevu."] = "Only if no tanking is planned.",
  ["Signaler les achats facultatifs chez le maître de classe et dans les infobulles ; dans le grimoire, OPTIONAL se place à droite de BEST. Pendant le leveling (avant le niveau 60), selon tous tes rôles et spécialisations. L'infobulle distingue le sort facultatif, le rang supplémentaire reportable et le cas où le rang 1 suffit pour l'usage conseillé, sans afficher les notes de recherche. Ce conseil ne retire aucun sort et reste indépendant d'ECO. La case Icônes doit aussi être activée pour voir le badge."] = "Mark optional purchases at trainers and in tooltips; in the spellbook, OPTIONAL appears beside BEST. Applies while leveling (before level 60), according to all selected roles and specializations. Tooltips distinguish optional spells, deferrable extra ranks and cases where rank 1 suffices. Does not remove spells and is independent of ECO. Icons must also be enabled to see the badge.",
  ["Signaler les rangs supérieurs à acheter"] = "Mark higher ranks to buy",
  ["Signaler les recettes déjà apprises"] = "Mark already-learned recipes",
  ["Signaler les sorts, talents et recettes récemment appris. La liste est conservée après rechargement et remplacée lorsqu’un nouvel apprentissage est enregistré. Une visite sans achat conserve la liste précédente. À la première utilisation, les sorts déjà connus du dernier palier accessible sont présélectionnés si leurs niveaux sont connus."] = "Mark recently learned spells, talents and recipes. The list survives reloads and is replaced when new learning is recorded. An empty trainer visit keeps the previous list. First use selects known spells from the latest accessible tier when their required levels are available.",
  ["Skills Already Known devient Skills & More. Retrouve le nouveau nom dans les options, la minicarte et les infobulles, avec la signature By CryptoLogiq dans la fenêtre des options."] = "Skills Already Known becomes Skills & More. The new name appears in options, on the minimap and in tooltips, with By CryptoLogiq in the options window.",
  ["Soigner les alliés pour maintenir le groupe en vie."] = "Heal allies to keep the group alive.",
  ["Soin en groupe; les degats peuvent compter en solo. Ne pas marquer le premier achat de Resurrection."] = "Group healing; damage can matter solo. Do not mark the first Resurrection purchase.",
  ["Soins ciblés et soins sur plusieurs alliés dans une même boîte à outils."] = "Targeted and multi-ally healing in one toolkit.",
  ["Soins ciblés, soutien varié et nouveaux outils pour le groupe."] = "Targeted healing, varied support and new group tools.",
  ["Sorts / compétences"] = "Spells / skills",
  ["Sorts du familier (/sam pet)"] = "Pet spells (/sam pet)",
  ["Souplesse pour exploiter les outils du chasseur et les capacités du familier."] = "Flexibility to use hunter tools and pet abilities.",
  ["Soutien des totems et nouveaux outils de récupération de mana."] = "Totem support and new mana-recovery tools.",
  ["Soutien utile au groupe et progression solo accessible."] = "Useful group support and approachable solo progress.",
  ["Soutien varié : bonus, affaiblissements, contrôles et soins de secours."] = "Versatile support: buffs, debuffs, control and emergency healing.",
  ["Spécialisation"] = "Specialization",
  ["Spécialisation : "] = "Specialization: ",
  ["Spécialisation suivie pour ce rôle. La sélection est conservée si tu décoches puis recoches le rôle."] = "Specialization followed for this role. Your selection is kept if you disable and re-enable the role.",
  ["Survie"] = "Survival",
  ["Survie au contact, utile en solo et contre les joueurs."] = "Melee survival useful solo and against players.",
  ["Survie face aux attaques au corps à corps, dans les deux activités."] = "Survival against melee attacks in both activities.",
  ["Survie personnelle utile sous les attaques, notamment en PvP et en solo."] = "Personal survival under attack, especially in PvP and solo play.",
  ["Survie propose un rythme offensif soutenu et utilise plus largement les possibilités du chasseur, à distance comme au corps à corps selon le combat et le choix de talents. Les pièges et les contrôles aident à gérer les déplacements ennemis. L'arbre prend davantage de relief une fois ses talents clés obtenus, plutôt que dès les tout premiers niveaux."] = "Survival has an active offensive rhythm and uses more of the hunter's tools, at range or in melee depending on the fight and talents. Traps and control manage enemy movement. The tree develops once key talents are acquired rather than at the earliest levels.",
  ["Sélection initiale : sorts déjà connus du palier de niveau "] = "Initial selection: known spells from level tier ",
  ["Talent Spec and Role"] = "Talent Spec and Role",
  ["Talents"] = "Talents",
  ["Temps fort offensif de la spécialisation Élémentaire."] = "An offensive power window for Elemental.",
  ["Temps fort offensif à utiliser en tenant compte du risque défensif."] = "An offensive power window whose defensive risk must be considered.",
  ["Totems et contrôles apportant du soutien au groupe."] = "Totems and control support the group.",
  ["Un badge LEVELING signale l’arbre conseillé en priorité pour progresser en solo dans chaque classe. Les infobulles des arbres et du grimoire décrivent uniquement la spécialisation survolée."] = "A LEVELING badge marks each class's main solo leveling recommendation. Tree and spellbook tooltips describe only the hovered specialization.",
  ["Un bon résultat demande de choisir quand protéger et quand soigner."] = "Good results require choosing when to shield and when to heal.",
  ["Un lanceur de sorts à distance qui affaiblit ses ennemis avec des dégâts sur la durée, puis utilise ses drains entre les renouvellements. Il peut entretenir ses effets sur plusieurs adversaires tout en s'appuyant sur son démon. Son efficacité augmente quand les combats lui laissent le temps d'installer et de maintenir ces effets."] = "A ranged caster that weakens enemies with damage over time, then uses drains between refreshes. Maintain effects on multiple opponents while relying on your demon. Effectiveness grows when fights last long enough to establish and sustain those effects.",
  ["Un soin immédiat peut sauver un allié dans les deux activités."] = "An immediate heal can save an ally in both activities.",
  ["Une dépense trop rapide peut laisser le mage sans mana."] = "Spending too quickly can leave you without mana.",
  ["Une incantation instantanée apporte dégâts ou réactivité."] = "An instant cast provides damage or a quick response.",
  ["Une part de son utilité est commune aux autres spécialisations de chaman."] = "Some utility is shared with other shaman specializations.",
  ["Une partie du résultat dépend de la fréquence des critiques."] = "Results partly depend on critical-hit frequency.",
  ["Une progression centrée sur les soins est surtout adaptée au jeu en groupe."] = "Healing-focused leveling is mainly suited to group play.",
  ["Utile en PvE et contre les joueurs, selon ta spécialisation et le combat."] = "Useful in PvE and against players, depending on your specialization and the encounter.",
  ["Utile selon la situation ; tu peux l'apprendre et l'utiliser."] = "Useful depending on the situation; you can learn and use it.",
  ["Utilitaire situationnel ; conserve son intérêt pour le butin ou les déplacements en camouflage."] = "Situational utility; still useful for loot or moving while stealthed.",
  ["Utilitaire; ce sort n'est pas une economie de rangs multiples."] = "Utility; this is not advice to save across multiple ranks.",
  ["Utilitaire; conserver si interruption, fuite ou soutien de groupe. Pas ECO automatique."] = "Utility; keep for interrupts, escaping or group support. Not automatically ECO.",
  ["Valider mes choix"] = "Confirm my choices",
  ["Vindicte"] = "Retribution",
  ["Vindicte est la voie de dégâts de mêlée du paladin : ses attaques avec une arme se combinent à des effets sacrés, aux sceaux et au Jugement. Il conserve les bénédictions, auras et protections qui lui permettent d'aider son groupe. Bien jouer consiste donc aussi à utiliser ce soutien au bon moment, sans abandonner inutilement sa pression offensive."] = "Retribution is the paladin's melee damage path: weapon attacks combine with Holy effects, seals and Judgement. Blessings, auras and protections still help the group. Good play includes timely support without needlessly abandoning offensive pressure.",
  ["Vindicte est un choix simple et autonome pour les quêtes, avec des attaques régulières, des protections et des soins personnels. Garde une arme adaptée et surveille ta mana."] = "Retribution is a straightforward, self-sufficient questing choice, with steady attacks, protection and self-healing. Keep a suitable weapon and watch your mana.",
  ["Voleur"] = "Rogue",
  ["Vérifier le récapitulatif avant d'activer les conseils pour ces rôles et spécialisations."] = "Review the recap before activating advice for these roles and specializations.",
  ["Vérifier un récapitulatif des rôles et spécialisations avec OK / Annuler avant d’activer les conseils. Une sélection non validée est reproposée au prochain chargement."] = "Confirm a recap of roles and specializations with OK / Cancel before activating advice. Unconfirmed choices are offered again next login or reload.",
  ["[LEVELING] — choix conseillé pour progresser en solo"] = "[LEVELING] — recommended choice for solo leveling",
  ["activé"] = "enabled",
  ["désactivé"] = "disabled",
  ["la dernière version"] = "the latest version",
  ["|cff00ccffECO|r : rang suffisant pour le leveling selon ton rôle ; économie d'or en reportant des achats, pas d'économie de mana garantie."] = "|cff00ccffECO|r: sufficient rank for the recommended leveling use; saves training gold by delaying purchases, not guaranteed mana.",
  ["|cff00ccffOPTIONAL|r : achat facultatif en leveling pour ton rôle. S'ajoute à droite de BEST ; L'infobulle rappelle qu'il s'agit d'une économie d'or sur un achat facultatif. Facultatif ne veut pas dire inutile."] = "|cff00ccffOPTIONAL|r: a leveling purchase that can wait for your role. Appears beside BEST; the tooltip explains the training-gold advice. Optional does not mean useless.",
  ["|cff33ff33Avantages|r"] = "|cff33ff33Advantages|r",
  ["|cff33ff33BEST|r : plus haut rang appris, même s'il est seul ; puissance et effets de ce rang."] = "|cff33ff33BEST|r: highest learned rank, even alone; strength and effects of that rank.",
  ["|cff33ff33NEW +|r : sort apprenable maintenant, contour vert et halo animé."] = "|cff33ff33NEW +|r: learnable now, green outline and animated glow.",
  ["|cff4dff4dAvantages|r"] = "|cff4dff4dAdvantages|r",
  ["|cffaaaaaaLOW|r : rang inférieur appris, aux dégâts, soins ou effets potentiellement réduits. Certains contrôles ont une limite de niveau."] = "|cffaaaaaaLOW|r: an older learned rank with potentially reduced damage, healing or effects. Some control spells have target-level limits.",
  ["|cffff3333NOT NOW|r : autre indisponibilité, contour rouge."] = "|cffff3333NOT NOW|r: otherwise unavailable, red outline.",
  ["|cffff5966[PVP]|r : principalement intéressant contre les joueurs. |cff59d9ff[PVE PVP]|r : utile dans les deux activités. Ces repères d’usage apparaissent sur les talents vérifiés et les sorts apprenables du maître ; ils ne rendent aucun choix obligatoire et restent indépendants d’ECO / OPTIONAL."] = "|cffff5966[PVP]|r: mainly useful against players. |cff59d9ff[PVE PVP]|r: useful in both activities. These usage markers appear on reviewed talents and learnable trainer spells; they do not make any choice mandatory and are independent of ECO / OPTIONAL.",
  ["|cffff7359Inconvénients|r"] = "|cffff7359Drawbacks|r",
  ["|cffffcc00Skills & More:|r configuration disponible après le combat."] = "|cffffcc00Skills & More:|r settings are available after combat.",
  ["|cffffcc00Skills & More:|r utilise /reload après le combat."] = "|cffffcc00Skills & More:|r use /reload after combat.",
  ["|cffffd100BUY NEW RANK|r : un rang supérieur accessible à ton niveau reste à apprendre. Les achats ECO / OPTIONAL ne déclenchent pas cette alerte. LOW signifie qu'un rang supérieur est déjà appris."] = "|cffffd100BUY NEW RANK|r: an accessible higher rank remains to learn. ECO / OPTIONAL purchases do not trigger this alert. LOW means a higher rank is already learned.",
  ["|cffffd100NEXT|r : disponible au prochain palier de niveau pair, contour et fond jaunes."] = "|cffffd100NEXT|r: available at the next even-level milestone, yellow outline and background.",
  ["|cffffd100[LEVELING] — choix conseillé pour progresser en solo|r"] = "|cffffd100[LEVELING] — recommended choice for solo leveling|r",
  ["À la première utilisation, RECENT présélectionne les sorts déjà connus du dernier palier accessible à ton niveau lorsque leurs niveaux requis sont disponibles. Les prochains apprentissages remplacent cette sélection initiale."] = "On first use, RECENT selects already-known spells from the latest accessible level tier when required levels are available. Your next learning replaces this initial selection.",
  ["À l’aise sur les combats longs et contre plusieurs ennemis séparés."] = "Comfortable in long fights and against spread-out enemies.",
  ["Élémentaire"] = "Elemental",
  ["Élémentaire combat à distance avec des éclairs et des sorts de feu, tout en soutenant le groupe grâce aux totems. Les attaques qui touchent plusieurs ennemis proches tiennent une place importante dans son arsenal. Le rythme offensif reste abordable, mais les gros enchaînements peuvent coûter beaucoup de mana et demandent de bien placer ses totems."] = "Elemental fights at range with lightning and Fire spells while supporting the group with totems. Attacks hitting several nearby enemies are important. The offense is approachable, but strong sequences cost mana and require good totem positioning.",
  ["Éléments affichés"] = "Displayed elements",
  ["Équilibre"] = "Balance",
  ["Équilibre joue à distance avec des sorts de nature et des arcanes, ainsi que des dégâts sur la durée. Les talents de Forever encouragent à alterner les grandes incantations selon les effets actifs. Le druide peut aussi interrompre son rythme offensif pour contrôler des ennemis ou apporter des soins de secours, au prix de temps et de mana."] = "Balance fights at range with Nature and Arcane spells and damage over time. Forever talents encourage alternating major casts according to active effects. The druid can interrupt offense to control enemies or provide emergency healing, at a cost in time and mana.",
  ["— conseillé pour progresser en solo"] = "— recommended for solo leveling",
  ["Le choix manuel de langue est correctement repris après un rechargement de l’interface."] = "The selected language is correctly restored after reloading the interface.",
  ["La version officielle démarre correctement lorsque la copie DEV est présente mais non chargée."] = "The official addon starts correctly when the DEV copy is present but not loaded.",
  ["Les compétences de familiers déjà apprises sont reconnues dans la liste de TrainerSpells."] = "Previously learned pet abilities are recognized in the TrainerSpells list.",
  ["PET_ABILITIES_LABEL"] = "Pet abilities",
  ["Les livres de familiers gardent leurs marqueurs quel que soit le démon actif. Le grimoire des familiers indique les rangs appris, les rangs accessibles à acheter et les apprentissages récents."] = "Pet books keep their markers regardless of the active demon. Pet spellbooks show learned ranks, available rank upgrades and recent learning.",
  ["Un contour doré lumineux distingue les livres du familier actuellement invoqué."] = "A bright gold border highlights books for your currently summoned pet.",
  ["SURVIVAL_DRUID_339"] = "Roots an enemy so you can gain distance. Higher ranks may improve control.",
  ["SURVIVAL_DRUID_5211"] = "Stuns an enemy to interrupt an attack or make room to escape.",
  ["SURVIVAL_DRUID_1850"] = "Increases movement speed to escape or reposition.",
  ["SURVIVAL_DRUID_16689"] = "Helps root enemies that strike you so you can get away.",
  ["SURVIVAL_DRUID_2893"] = "Removes poisons from you or an ally.",
  ["SURVIVAL_HUNTER_13163"] = "Improves dodge to reduce incoming melee damage.",
  ["SURVIVAL_MAGE_1953"] = "Helps you escape, reposition or break certain crowd controls.",
  ["SURVIVAL_MAGE_1463"] = "Absorbs damage at the cost of mana: an emergency tool rather than a shield to keep active all the time.",
  ["SURVIVAL_MAGE_130"] = "Slows your fall to prevent fall damage.",
  ["SURVIVAL_PALADIN_633"] = "A major emergency heal for you or an ally.",
  ["SURVIVAL_PRIEST_8122"] = "Temporarily drives enemies away. Fleeing enemies may pull others; higher ranks can affect more targets.",
  ["SURVIVAL_WARLOCK_755"] = "Heals your demon using your own health to keep it in the fight. Watch your health while channeling.",
  ["SURVIVAL_LABEL"] = "Show SURVIVAL markers",
  ["SURVIVAL_DESCRIPTION"] = "Marks reviewed escape tools, defensive controls and emergency healing. Hover over a marker for its use. This marker does not mean rank 1 is always sufficient.",
  ["SURVIVAL_HINT"] = "Survival tool: its use depends on the situation.",
  ["SURVIVAL_LEGEND"] = "|cff66ffaaSURVIVAL|r: an escape tool, defensive control or emergency heal. Can accompany BEST or ECO; hover over the marker for its use.",
  ["Le repère SURVIVAL signale une première sélection d’outils de fuite, de contrôle défensif et de soin d’urgence dans le grimoire, chez les maîtres et dans TrainerSpells. Son affichage est réglable dans Affichage."] = "SURVIVAL marks an initial selection of escape tools, defensive controls and emergency healing in the spellbook, at trainers and in TrainerSpells. Toggle it in Display.",
  ["AOE_MELEE"] = "Deals damage to multiple nearby enemies in melee range.",
  ["AOE_CHANNEL"] = "Deals damage in an area while channeling.",
  ["AOE_MULTITARGET"] = "Hits multiple enemies: check nearby targets before firing.",
  ["AOE_AROUND"] = "Deals damage to enemies around you.",
  ["AOE_GROUND"] = "Deals damage in the targeted ground area.",
  ["AOE_CONE"] = "Deals damage to multiple enemies in front of you.",
  ["AOE_UNDEAD_DEMON"] = "Deals area damage to the creature types specified by the spell.",
  ["AOE_CLEAVE"] = "Allows you to hit an additional nearby target.",
  ["AOE_TOTEM"] = "The totem deals damage to nearby enemies.",
  ["AOE_SELF_DAMAGE"] = "Deals damage around you and also hurts you: watch your health.",
  ["AOE_LABEL"] = "Show AOE markers",
  ["AOE_HINT"] = "Area damage or damage to multiple targets.",
  ["AOE_DESCRIPTION"] = "Marks spells that hit multiple enemies in the spellbook, at trainers and in TrainerSpells. They are not classified as OPTIONAL by default.",
  ["AOE_LEGEND"] = "|cff66ddffAOE|r: area damage or damage to multiple targets, such as Blizzard, Rain of Fire and Consecration.",
  ["Le repère AOE identifie les dégâts de zone et les attaques multicibles, notamment Blizzard, Pluie de feu et Consécration. Son affichage est réglable dans Affichage."] = "AOE marks area damage and attacks that hit multiple targets, including Blizzard, Rain of Fire and Consecration. Toggle it in Display.",
  ["Les sorts de zone reconnus ne sont plus conseillés comme des achats OPTIONAL."] = "Recognized area-damage spells are no longer recommended as OPTIONAL purchases.",
  ["AOE_TALENT_ACTIVE"] = "Allows you to hit multiple enemies. Read the talent description for its conditions.",
  ["AOE_TALENT_IMPROVES"] = "Improves an area spell through damage, cost, range or control, depending on the talent. It does not trigger an area attack by itself.",
  ["AOE_TALENT_SPREAD"] = "Allows an effect to spread to nearby enemies under the talent conditions.",
  ["AOE_FIRE_NOVA"] = "Deals damage around your active Fire totem.",
  ["Les repères AOE couvrent les neuf classes et les talents vérifiés de leurs arbres, y compris les améliorations de sorts de zone. Les marqueurs restent sous les icônes sans masquer les points dépensés."] = "AOE markers cover all nine classes and reviewed talents in their trees, including area-spell improvements. Markers stay below icons without covering spent talent points.",
  ["CLASS_DRAIN_SOUL"] = "An essential Warlock skill: provides Soul Shards needed for several summons and abilities. Rank 1 retains this utility; higher ranks notably increase damage.",
  ["CLASS_HINT"] = "A skill needed for a core class mechanic.",
  ["CLASS_LABEL"] = "Show CLASS markers",
  ["CLASS_DESCRIPTION"] = "Marks skills essential to reviewed class mechanics. For Warlocks, Drain Soul provides Soul Shards. This marker does not make every rank mandatory.",
  ["CLASS_LEGEND"] = "|cffcca6ffCLASS|r: a skill essential to a class mechanic. Can accompany ECO at rank 1 or BEST on the highest learned rank.",
  ["Drain d’âme porte le repère CLASS pour rappeler son rôle dans la création de fragments d’âme. Il n’affiche plus OPTIONAL ; le rang 1 peut conserver ECO et le plus haut rang appris BEST."] = "Drain Soul carries the CLASS marker to highlight its role in creating Soul Shards. It no longer shows OPTIONAL; rank 1 can retain ECO and the highest learned rank BEST.",
  ["TOOLTIP_BADGES_LABEL"] = "Show badges above tooltips",
  ["TOOLTIP_BADGES_DESCRIPTION"] = "Repeats the spell markers above its tooltip: rank, OPTIONAL, SURVIVAL, AOE, CLASS and RECENT as applicable. They move below the frame if there is not enough room at the top of the screen.",
  ["Les badges du sort peuvent aussi s’afficher au-dessus de son infobulle, avec une option dédiée dans Affichage. Ils passent sous le cadre si le haut de l’écran manque de place."] = "Spell badges can also appear above their tooltip, with a dedicated Display option. They move below the frame when there is not enough room at the top of the screen.",
  ["BADGE_EDITOR_TITLE"] = "Spell badges",
  ["BADGE_EDITOR_HELP"] = "Customize spells and talents for your class. Select a listed spell or enter an ID, then save your choices. BEST, LOW, BUY NEW RANK, RECENT and learned/learnable states remain automatic.",
  ["BADGE_CURRENT_CLASS"] = "Current class: %s",
  ["BADGE_SCOPE"] = "Apply these settings to",
  ["BADGE_SCOPE_CHARACTER"] = "This character",
  ["BADGE_SCOPE_CLASS"] = "This class across my account",
  ["BADGE_PRECEDENCE"] = "Character settings take priority over class settings. Within one scope, an exact ID takes priority over an all-ranks rule. “Inherit” keeps the class setting or the supplied advice.",
  ["BADGE_FILTER"] = "Filter list by badge",
  ["BADGE_ALL"] = "All listed spells",
  ["BADGE_SPELL"] = "Spell or talent to edit",
  ["BADGE_ADD_ID"] = "Add or select a spell ID",
  ["BADGE_ADD_HELP"] = "Enter the numeric spell ID, then confirm the field. The choices below apply only after Save.",
  ["BADGE_ALL_RANKS"] = "Apply to all ranks",
  ["BADGE_RANK_HELP"] = "Checked by default for a new ID. Other ranks are linked by the game-provided spell name. Unchecked: only this ID is changed.",
  ["BADGE_FIELD_usage"] = "Spell usage",
  ["BADGE_FIELD_combat"] = "PVP / PVE PVP activity",
  ["BADGE_FIELD_advice"] = "Purchase advice",
  ["BADGE_INHERIT"] = "Inherit previous setting",
  ["BADGE_NONE"] = "No badge in this category",
  ["BADGE_DEFAULT"] = "Supplied addon advice",
  ["BADGE_EFFECTIVE_FIELD"] = "%s: %s — %s",
  ["BADGE_SAVE"] = "Save my choices",
  ["BADGE_RESTORE"] = "Remove my rule for this spell",
  ["BADGE_RESTORE_CONFIRM"] = "Remove this rule from the selected scope? Inherited settings will apply again.",
  ["BADGE_INVALID_ID"] = "Enter a positive whole-number spell ID.",
  ["BADGE_UNKNOWN_ID"] = "The game has not recognized this spell yet. Check its ID or try again after its information loads.",
  ["BADGE_CUSTOM_REASON"] = "This marker comes from your custom badge settings.",
  ["BADGE_CUSTOM_OPTIONAL"] = "OPTIONAL — purchase can wait according to your custom setting.",
  ["Dans Custom, l’onglet Badges des sorts permet de modifier les repères des sorts et talents de sa classe, ou d’ajouter un ID. Les réglages s’appliquent au personnage ou à toute sa classe sur le compte, avec une option Tous les rangs cochée par défaut."] = "The new Spell badges tab lets you customize markers for your class spells and talents or add a spell ID. Settings apply to this character or the same class across your account, with All ranks checked by default.",
  ["Dans TrainerSpells, les compétences de démons mémorisées affichent une coche lorsqu’elles sont déjà apprises, même lorsque les noms des familiers sont traduits et les IDs des grimoires diffèrent de ceux des compétences."] = "Recorded demon abilities in TrainerSpells show a check when already learned, including localized pet names and grimoires whose IDs differ from their abilities.",
  ["DEV_TOOLTIP_HINT"] = "Skills & More development copy is active.",
  ["DEV_TOOLS_ENABLE"] = "Enable development tools",
  ["DEV_TOOLS_ENABLE_HELP"] = "Shows diagnostic reports, test commands and the button to replay first-time setup. Disabled by default and saved for this character. No reload required.",
  ["DEV_TOOLS_TITLE"] = "Development",
  ["DEV_TOOLS_DISABLED_HINT"] = "Skills & More: enable development tools in Display to use this command.",
  ["DEV_TOOLS_BOOK_COMMAND"] = "/sam bookdebug — spellbook",
  ["RESET_PLAYER_HELP"] = "Restore this character’s settings. Recorded pet spells and books are retained.",
  ["Une case dans Affichage permet d’activer les outils de développement et de diagnostic. L’onglet dédié et le bouton de test du premier lancement sont masqués lorsque ces outils sont désactivés."] = "A Display checkbox enables development and diagnostic tools. Their tab and the first-time setup test button stay hidden while these tools are disabled.",
  ["OPTIONS_HOME"] = "Overview",
  ["OPTIONS_NAV_HELP"] = "Choose a section under Skills & More in the list on the left to adjust display, roles or badges, or read the latest changes.",
  ["Les rubriques de réglages sont accessibles directement dans la colonne de gauche d’Options → AddOns, sous Skills & More, pour laisser davantage de place au contenu."] = "Settings sections are available directly in the left-hand list under Skills & More in Options → AddOns, leaving more room for their content.",
  ["Les explications des badges personnalisés et des conseils d’usage suivent correctement la langue choisie, y compris dans les infobulles hors du grimoire."] = "Custom badge explanations and usage advice correctly follow the selected language, including tooltips outside the spellbook.",
  ["AOE_IMPROVE_RESOURCE"] = "Reduces the resource cost of the area attacks below. The talent does not launch an attack itself.",
  ["AOE_IMPROVE_DAMAGE"] = "Increases the damage of the area spells or multi-target attacks below.",
  ["AOE_IMPROVE_CRIT"] = "Increases the critical strike chance of the area spell below.",
  ["AOE_IMPROVE_SLOW"] = "Adds a slowing effect to the area spell below.",
  ["AOE_IMPROVE_REACH"] = "Increases the range or radius of the area spells below, depending on the spell.",
  ["AOE_IMPROVE_MANA"] = "Reduces the mana cost of the area spells below. The talent does not launch an attack itself.",
  ["AOE_IMPROVE_GROUND"] = "Improves your Holy spell damage against the first enemies entering Consecration. An offensive use, including hybrid builds or PvP: this talent does not directly improve healing. AOE describes its link to an area, not a recommendation for every healer.",
  ["AOE_IMPROVE_RADIUS"] = "Increases the radius of the area spell below.",
  ["AOE_IMPROVE_HOLY_NOVA"] = "Strengthens Holy damage and lets Holy Fire periodic damage make Holy Nova free, under the talent’s conditions.",
  ["AOE_IMPROVE_SPREAD"] = "Lets the spell below spread to nearby enemies when its target dies. The base spell is not an area attack without this interaction.",
  ["AOE_IMPROVE_FIRE"] = "Improves Fire Nova damage and cooldown, and Magma Totem duration.",
  ["AOE_IMPROVE_RANGE"] = "Increases the range of the multi-target spells below.",
  ["AOE_IMPROVE_STUN"] = "Lets the area spells below stun enemies they hit, under the talent’s conditions.",
  ["AOE_IMPROVE_WHIRLWIND"] = "Reduces Whirlwind’s cooldown and increases its damage against the closest enemy.",
  ["AOE_RELATED_HEADER"] = "Affected spells",
  ["AOE_RELATED_PENDING"] = "Description currently unavailable. Hover again after the spell data has loaded.",
  ["AOE_RELATED_UNKNOWN"] = "Spell %d",
  ["Les talents qui améliorent des sorts de zone précisent leur effet et présentent les sorts concernés avec leur icône et leur description du jeu."] = "Talents that improve area spells explain their effect and show the affected spells with their icons and in-game descriptions.",
  ["SPELL_HINT_JUDGEMENT_SEAL"] = "Judgement requires an active seal. If you cannot use it, remember to activate a seal before casting Judgement.",
  ["L’infobulle de Jugement rappelle d’activer un sceau pour pouvoir utiliser ce sort."] = "Judgement’s tooltip reminds you to activate a seal before using the spell.",
  ["CUSTOM_SETTINGS_TITLE"] = "Custom",
  ["La rubrique Custom regroupe les personnalisations ; son premier onglet Badges des sorts permet de modifier les repères."] = "The Custom section groups player customizations, starting with the Spell badges tab for editing markers.",
  ["UTILITY_KICK"] = "Interrupts an enemy spell cast. Casts immune to interrupts remain protected.",
  ["UTILITY_BEAR_KICK"] = "Feral Charge in Bear Form interrupts the target. The Cat Form version does not.",
  ["UTILITY_SHIELD_KICK"] = "Interrupts an enemy spell cast; requires a shield and the spell’s other conditions.",
  ["UTILITY_PET_KICK"] = "Felhunter interrupt: requires this demon and its available ability.",
  ["UTILITY_KICK_AGGRO"] = "Interrupts a spell cast and explicitly generates high threat. This is not a taunt.",
  ["UTILITY_TAUNT"] = "Taunts the target into attacking the caster, unless immune.",
  ["UTILITY_FORCED_ATTACK"] = "Temporarily forces affected enemies to attack the caster. This does not guarantee keeping their attention after the effect ends.",
  ["UTILITY_FORCED_THREAT"] = "Temporarily forces the target to attack the caster and generates threat. This does not guarantee matching the leading threat like Taunt.",
  ["UTILITY_SEAL_TAUNT"] = "This seal lets Judgement taunt the target. Activating the seal alone does not taunt it.",
  ["UTILITY_AGGRO"] = "The spell description explicitly states additional threat generation. This badge does not mean the target is forced to attack the caster.",
  ["UTILITY_THREAT_BUFF"] = "Increases threat generated by Holy attacks while active. This is not a taunt.",
  ["UTILITY_PET_THREAT"] = "Generates threat for the pet; do not confuse it with a tank’s forced taunt.",
  ["UTILITY_TOTEM_THREAT"] = "The totem generates threat on nearby enemies to draw their attention. This is not a taunt by the shaman.",
  ["KICK_LABEL"] = "Show KICK — interrupts",
  ["KICK_DESCRIPTION"] = "Identifies verified interrupts, not every stun or silence. Can combine with AGGRO.",
  ["TAUNT_LABEL"] = "Show TAUNT — taunts",
  ["TAUNT_DESCRIPTION"] = "Identifies verified taunts and forced-attack effects. Tooltips explain conditions, including Seal of Fury with Judgement.",
  ["AGGRO_LABEL"] = "Show AGGRO — additional threat",
  ["AGGRO_DESCRIPTION"] = "Identifies spells whose descriptions explicitly state additional threat. Does not mark every damage or healing spell.",
  ["COMBINATION_LABEL"] = "Show combination hints",
  ["COMBINATION_DESCRIPTION"] = "Show a short selection of related-spell hints in tooltips. Talent requirements are stated; no full rotation is added.",
  ["COMBO_SWIFTMEND"] = "Swiftmend requires an active Rejuvenation or Regrowth on the target. If neither is present, apply that heal over time first. In Forever, Swiftmend does not consume it.",
  ["COMBO_DRUID_SWIFTNESS"] = "This talent can make Healing Touch instant: activate Nature’s Swiftness, then cast the heal in an emergency. The bonus applies to the next eligible Nature spell.",
  ["COMBO_MONGOOSE"] = "Mongoose Bite normally requires you to have dodged an attack. Aspect of the Monkey increases dodge chance, which can help make it available. Some Survival talents change this requirement.",
  ["COMBO_ICE_LANCE"] = "Ice Lance deals more damage to frozen targets, for example after Frost Nova. A slow alone is not enough. If you have Fingers of Frost, its active proc also enables this interaction.",
  ["COMBO_INNER_FOCUS"] = "Use Inner Focus before a large eligible heal, such as Prayer of Healing or Greater Heal, to save its mana cost. The critical strike bonus only applies to spells that can critically hit.",
  ["COMBO_COLD_BLOOD"] = "Cold Blood can set up a stronger Eviscerate with your combo points. Another eligible attack can use the bonus first; the critical strike bonus does not guarantee hitting the target.",
  ["COMBO_FIRE_NOVA"] = "Fire Nova erupts around your active Fire totem, not around you. Place a Fire totem near enemies before casting it.",
  ["COMBO_RIPTIDE"] = "Riptide improves Chain Heal when you cast it directly on the target carrying the effect. Choose that target for the first heal, not merely a nearby ally.",
  ["COMBO_SHAMAN_SWIFTNESS"] = "This talent allows an instant Healing Wave: activate Nature’s Swiftness, then cast the heal in an emergency. The next Nature spell must be eligible.",
  ["COMBO_CONFLAGRATE"] = "Conflagrate requires your Immolate on the target. It normally consumes it; maximum points in Shadow and Flame change that behavior. Do not assume the talent applies if you have not learned it.",
  ["COMBO_REVENGE"] = "Revenge becomes available after you block, dodge or parry. Shield Block can help produce the block, but an enemy still needs to attack you.",
  ["Les repères KICK, TAUNT et AGGRO distinguent les interruptions, les provocations ou attaques forcées, et les sorts indiquant explicitement de la menace supplémentaire. Un sort peut cumuler plusieurs usages."] = "KICK, TAUNT and AGGRO distinguish interrupts, taunts or forced attacks, and spells explicitly generating additional threat. A spell can have multiple uses.",
  ["Une sélection de 12 astuces explique des interactions comme Javelot de glace sur cible gelée, Prompte guérison avec un soin sur la durée, Nova de feu avec un totem de feu et Conflagration avec Immolation. Leur affichage est réglable dans Affichage."] = "A selection of 12 hints explains interactions such as Ice Lance on frozen targets, Swiftmend with a heal over time, Fire Nova with a Fire totem and Conflagrate with Immolate. Their display can be changed in Display.",
  ["Les catégories KICK, TAUNT et AGGRO peuvent être affichées séparément et personnalisées dans Custom, onglet Badges des sorts."] = "KICK, TAUNT and AGGRO can be shown independently and customized under Custom, in the Spell badges tab.",
  ["STANCE_BEAR"] = "Tank-oriented form: improves durability and gives access to Bear abilities. Your equipment and talents still matter.",
  ["STANCE_CAT"] = "Melee damage-oriented form, using Energy and combo points. This marker does not change your selected role.",
  ["STANCE_MOONKIN"] = "Spell damage-oriented form. It prevents healing spells: leave this form if you need to heal.",
  ["STANCE_SHADOW"] = "Shadow damage-oriented form. Healing spells are unavailable in this form.",
  ["STANCE_REDEMPTION"] = "Temporary healing-oriented form triggered on death with the Spirit of Redemption talent. It is not a stance to activate voluntarily or advice to die.",
  ["STANCE_DEFENSIVE"] = "Baseline tanking stance: reduces damage taken and increases threat. A tank may change stance to use particular abilities.",
  ["STANCE_BATTLE"] = "Versatile stance for attacking and accessing certain abilities. The DPS marker does not prevent a tank from using it when useful.",
  ["STANCE_BERSERKER"] = "Offensive damage-oriented stance with greater defensive risks. It does not replace Defensive Stance for taking hits.",
  ["STANCE_RIGHTEOUS_FURY"] = "Tank-oriented effect: increases threat from your Holy attacks. Check that it suits your role before enabling it in a group.",
  ["STANCE_SEAL_FURY"] = "Tank-oriented seal: enables taunting through Judgement. The seal’s and equipment’s conditions still apply.",
  ["TANK_USAGE_LABEL"] = "Show TANK — tank-oriented forms and effects",
  ["HEAL_USAGE_LABEL"] = "Show HEAL — healing-oriented forms and effects",
  ["DPS_USAGE_LABEL"] = "Show DPS — offensive forms and stances",
  ["ROLE_USAGE_DESCRIPTION"] = "Shows the orientation of reviewed forms, stances and effects. Does not choose your role, change talents or mean another role can never use the spell.",
  ["UTILITY_DEFENSIVE_THREAT"] = "Increases threat generated while the stance is active. This is not a direct taunt.",
  ["Les repères TANK, HEAL et DPS indiquent l’orientation de formes, postures et effets vérifiés, notamment ours, félin, chouettide, forme d’Ombre et Fureur vertueuse. Ils peuvent se cumuler avec AGGRO ou TAUNT sans changer le rôle choisi."] = "TANK, HEAL and DPS markers show the orientation of reviewed forms, stances and effects, including Bear, Cat, Moonkin, Shadowform and Righteous Fury. They can combine with AGGRO or TAUNT without changing your chosen role.",
  ["SURVIVAL_DRUID_22812"] = "Reduces incoming physical damage and limits spell pushback from attacks. Check the spell’s conditions.",
  ["SURVIVAL_DRUID_22842"] = "Converts Rage into healing in Bear Form: keep enough Rage to benefit.",
  ["SURVIVAL_HUNTER_5384"] = "Can make enemies lose interest in you and allow leaving combat. Does not guarantee a successful escape.",
  ["SURVIVAL_HUNTER_781"] = "Reduces your melee threat to help your pet or an ally regain the enemy’s attention.",
  ["SURVIVAL_HUNTER_19263"] = "Temporarily improves your defense against attacks under the talent’s conditions; it is not invulnerability.",
  ["SURVIVAL_HUNTER_1499"] = "Incapacitates a susceptible target to give you breathing room. Damage can break the control.",
  ["SURVIVAL_HUNTER_5116"] = "Slows the target to keep distance or escape. A slow is not a root.",
  ["SURVIVAL_HUNTER_2974"] = "Slows a melee enemy to help you get away.",
  ["SURVIVAL_HUNTER_13809"] = "Creates a slowing area to gain distance from multiple enemies.",
  ["SURVIVAL_MAGE_122"] = "Roots nearby enemies to create distance. Damage can break the roots.",
  ["SURVIVAL_MAGE_11958"] = "Temporary immunity: you cannot attack, move or cast spells during the effect.",
  ["SURVIVAL_MAGE_11426"] = "Absorbs damage and protects your spellcasts while the shield holds.",
  ["SURVIVAL_MAGE_543"] = "Absorbs Fire damage. Other damage types are not covered by this spell.",
  ["SURVIVAL_MAGE_6143"] = "Absorbs Frost damage. Other damage types are not covered by this spell.",
  ["SURVIVAL_MAGE_118"] = "Temporarily disables a susceptible target. Damage can break the effect and the target regenerates health while controlled.",
  ["SURVIVAL_PALADIN_498"] = "Temporary emergency protection; prevents your attacks and physical abilities during the effect. Applies Forbearance and cannot be used while that debuff is active.",
  ["SURVIVAL_PALADIN_642"] = "Emergency immunity subject to Forbearance. While tanking, enemies may turn away from you during the immunity.",
  ["SURVIVAL_PALADIN_1022"] = "Protects against physical attacks but prevents the recipient’s physical attacks. In a group, consider whom enemies may attack instead.",
  ["SURVIVAL_PALADIN_1044"] = "Helps you or an ally escape movement impairments covered by this spell.",
  ["SURVIVAL_PALADIN_853"] = "Stuns a susceptible target to stop its actions and give you breathing room. This control is not a school-lock KICK.",
  ["SURVIVAL_PALADIN_4987"] = "Removes harmful Magic, Poison or Disease effects covered by the spell from you or an ally.",
  ["SURVIVAL_PRIEST_17"] = "Absorbs damage to immediately protect you or an ally. Weakened Soul can prevent another application.",
  ["SURVIVAL_PRIEST_586"] = "Temporarily reduces your threat to help others regain enemies. It is neither invisibility nor a guaranteed combat exit.",
  ["SURVIVAL_PRIEST_6346"] = "Protects against the next Fear effect covered by the spell. It does not protect against every form of control.",
  ["SURVIVAL_ROGUE_5277"] = "Temporarily improves dodge against attacks it applies to; does not protect against every spell.",
  ["SURVIVAL_ROGUE_1856"] = "Lets you vanish and remove movement impairments. Damage or detection can compromise the escape.",
  ["SURVIVAL_ROGUE_2983"] = "Increases movement speed to escape or reposition.",
  ["SURVIVAL_ROGUE_2094"] = "Disorients a susceptible target to buy time; damage breaks the effect.",
  ["SURVIVAL_ROGUE_1776"] = "Briefly disables the target to gain breathing room or heal. Damage breaks the control; positioning requirements still apply.",
  ["SURVIVAL_ROGUE_1966"] = "Reduces your threat to help the tank hold the enemy. Does not guarantee the target stops attacking you.",
  ["SURVIVAL_SHAMAN_5730"] = "The totem can distract nearby enemies to give you breathing room; effectiveness depends on existing threat.",
  ["SURVIVAL_SHAMAN_2484"] = "Slows enemies near the totem to help escape or keep distance.",
  ["SURVIVAL_SHAMAN_8143"] = "Periodically removes certain Fear, Charm or Sleep effects from affected party members. Does not guarantee permanent immunity.",
  ["SURVIVAL_SHAMAN_2645"] = "Movement form for escaping or repositioning when its usage conditions allow.",
  ["SURVIVAL_WARLOCK_5782"] = "Makes a susceptible target flee to give you breathing room. Its escape can attract more enemies and damage can break the control.",
  ["SURVIVAL_WARLOCK_6789"] = "Briefly horrifies the target and restores your health according to the spell’s effects: an emergency tool.",
  ["SURVIVAL_WARLOCK_5484"] = "Makes several susceptible enemies flee. Account for casting time and the risk of attracting additional enemies.",
  ["SURVIVAL_WARLOCK_6229"] = "Absorbs Shadow damage; does not protect against every magic school.",
  ["SURVIVAL_WARLOCK_6201"] = "Prepares a Healthstone to use for emergency healing. Creating it does not itself heal you.",
  ["SURVIVAL_WARRIOR_871"] = "Greatly reduces incoming damage briefly. Requires the shield and stance conditions of the spell.",
  ["SURVIVAL_WARRIOR_12975"] = "Temporarily increases your health to survive an emergency. Watch for the effect ending.",
  ["SURVIVAL_WARRIOR_2565"] = "Temporarily improves shield blocking against affected attacks. It is not general immunity.",
  ["SURVIVAL_WARRIOR_676"] = "Disarms a susceptible enemy to limit weapon-based attacks. Some targets are immune.",
  ["SURVIVAL_WARRIOR_5246"] = "Temporarily drives off or disables susceptible enemies. Fleeing targets may attract additional enemies.",
  ["Les repères SURVIVAL couvrent désormais 56 familles de sorts des neuf classes, notamment Protection divine et ses deux rangs, les principales immunités, boucliers, fuites et réductions de dégâts."] = "SURVIVAL markers now cover 56 spell families across all nine classes, including both Divine Protection ranks and major immunities, shields, escapes and damage reductions.",
  ["STANCE_DEVOTION"] = "Protection-oriented aura: increases nearby members’ armor against applicable physical damage. Useful to the tank and group, whatever the paladin’s role.",
  ["STANCE_RETRIBUTION"] = "Damage-oriented aura: deals Holy damage to enemies striking protected members. Also useful to a tank taking attacks; it does not directly increase all group attacks.",
  ["STANCE_CONCENTRATION"] = "HEAL / DPS support: helps healers and spellcasters continue casting while taking damage. It is not general immunity to interrupts.",
  ["Les auras du paladin affichent leur usage : Dévotion TANK, Vindicte DPS et Concentration HEAL / DPS, avec une explication de leur utilité pour le groupe."] = "Paladin auras show their purpose: Devotion TANK, Retribution DPS and Concentration HEAL / DPS, with explanations of their group benefits.",
  ["TALENT_ADVICE_RECOMMENDED"] = "Recommended for: %s",
  ["TALENT_ADVICE_OFFENSIVE_HYBRID"] = "For an offensive hybrid build; improves damage, not healing directly.",
  ["TALENT_ADVICE_PVP_CONTEXT"] = "Primarily a PvP suggestion; its value depends on the build and activity.",
  ["Les talents dont la recommandation est vérifiée dans un guide affichent la spécialisation, le rôle et le contexte du build. Les variantes situationnelles sont distinguées du build standard."] = "Talents with a verified guide recommendation show their specialization, role and build context. Situational variants are distinguished from the standard build.",
  ["TALENT_BUILD_SHOCKPROT"] = "Shockprot, offensive PvE",
  ["TALENT_BUILD_SITUATIONAL"] = "Situational Shockprot variant; this is not the standard tank build.",
  ["TALENT_BUILD_RAID"] = "PvE raid",
  ["TALENT_BUILD_RAID_DUNGEON"] = "PvE raid / dungeon",
  ["TALENT_BUILD_SHOCKADIN_PVP"] = "PvP Shockadin, Holy tree",
  ["TALENT_BUILD_RETPROT_DUNGEON"] = "Retprot / PvE dungeon",
  ["TALENT_BUILD_DUNGEON"] = "PvE dungeon",
  ["TALENT_BUILD_STANDARD_RET"] = "standard Retribution, PvE",
  ["RECENT_SPARKLES_LABEL"] = "Sparkles: RECENT spells missing from action bars",
  ["RECENT_SPARKLES_DESCRIPTION"] = "Sparkle recently learned spells in the spellbook until their rank is detected on an action bar, including another page or a recognized macro. The RECENT badge remains after placement. Complex macros may not be recognized.",
  ["Dans le grimoire, des étincelles signalent les sorts RECENT dont le rang n’est pas détecté dans les barres d’action. Elles s’arrêtent après placement ; leur affichage est réglable dans Affichage."] = "In the spellbook, sparkles highlight RECENT spells whose rank is not detected on an action bar. They stop after placement and can be toggled in Display.",
  ["LEARNING_SPARKLES_LABEL"] = "Sparkles: available new learning",
  ["LEARNING_SPARKLES_DESCRIPTION"] = "Sparkle only NEW + icons at class and profession trainers, and recipes identified as unlearned at merchants and in loot. Respects display categories; tooltips never sparkle. Incomplete data receives no effect.",
  ["Les icônes NEW + scintillent chez les maîtres de classe et de métiers. Les recettes non apprises reconnues scintillent aussi chez les marchands et dans les fenêtres de butin. L’effet reste limité à l’icône et se règle dans Affichage."] = "NEW + icons sparkle at class and profession trainers. Recognized unlearned recipes also sparkle at merchants and in loot windows. The effect stays within the icon area and can be toggled in Display.",
  ["UNUSED_SPELL_TOOLTIP"] = "Newly acquired spell: no successful use recorded yet.",
  ["UNUSED_SPARKLES_LABEL"] = "Blue sparkles: unused RECENT spells",
  ["UNUSED_SPARKLES_DESCRIPTION"] = "Sparkle RECENT spells in blue after action-bar placement while they remain unused, in the spellbook and supported action bars. Stops after the first successful use of that rank. Tracking persists after reload; only a successful use confirmed by the game counts.",
  ["ACTION_BAR_CATEGORY"] = "Action bars",
  ["ACTION_BAR_CATEGORY_DESCRIPTION"] = "Show blue sparkles on unused RECENT spell icons in supported Blizzard / EllesmereUI action, stance, form and aura bars. Does not change buttons or their actions.",
  ["Les sorts RECENT placés dans les barres mais encore inutilisés scintillent en bleu, dans le grimoire et les barres Blizzard / EllesmereUI reconnues. Leur infobulle explique le repère ; il disparaît après la première utilisation réussie. Le suivi est conservé après rechargement."] = "RECENT spells placed on action bars but not yet used sparkle blue in the spellbook and supported Blizzard / EllesmereUI bars. Their tooltip explains the hint, which disappears after the first successful use. Tracking persists after reload.",
  ["Les barres de postures, formes et auras sont reconnues, y compris avec EllesmereUI : les sorts présents cessent d’être signalés comme absents des barres et peuvent scintiller en bleu tant qu’ils restent inutilisés."] = "Stance, form and aura bars are recognized, including with EllesmereUI: their spells are no longer flagged as missing from action bars and can sparkle blue while unused.",
  ["De nouveaux repères distinguent les usages des sorts : CLASS, AOE, SURVIVAL, KICK, TAUNT et AGGRO. Les infobulles expliquent leurs conditions ; plusieurs usages peuvent se cumuler."] = "New markers distinguish spell uses: CLASS, AOE, SURVIVAL, KICK, TAUNT and AGGRO. Tooltips explain their conditions; several uses can combine.",
  ["Les formes, postures et auras renseignées affichent TANK, HEAL ou DPS, notamment les auras du paladin. Ces indications ne changent pas le rôle choisi."] = "Supported forms, stances and auras show TANK, HEAL or DPS, including Paladin auras. These hints do not change the selected role.",
  ["Dans le grimoire, RECENT scintille en doré si le sort manque dans les barres, puis en bleu après placement tant qu’aucune utilisation réussie n’est enregistrée. Le suivi est conservé après rechargement et le badge RECENT reste après utilisation."] = "In the spellbook, RECENT sparkles gold while a spell is missing from action bars, then blue after placement until a successful use is recorded. Tracking survives reload and the RECENT badge remains after use.",
  ["Les étincelles bleues apparaissent aussi sur les barres Blizzard et EllesmereUI reconnues, y compris les barres de postures, formes et auras. L’infobulle explique le repère."] = "Blue sparkles also appear on supported Blizzard and EllesmereUI bars, including stance, form and aura bars. The tooltip explains the hint.",
  ["Les icônes NEW + scintillent chez les maîtres de classe et de métiers. Les recettes non apprises reconnues scintillent chez les marchands et dans le butin, uniquement autour de leur icône. Ces effets se règlent dans Affichage."] = "NEW + icons sparkle at class and profession trainers. Recognized unlearned recipes sparkle at merchants and in loot, only around their icon. These effects can be toggled in Display.",
  ["Dans Custom → Badges des sorts, personnalise les marqueurs d’usage, PvP et d’achat de ta classe, ou ajoute un sort par son ID. Les choix peuvent concerner ce personnage ou toute la classe sur le compte, avec Tous les rangs coché par défaut."] = "In Custom → Spell badges, customize your class’s usage, PvP and purchase markers, or add a spell by ID. Choices can apply to this character or the class across the account, with All ranks checked by default.",
  ["Les badges peuvent apparaître au-dessus des infobulles. Dans le grimoire, les catégories sont placées juste au-dessus de BEST, LOW ou ECO pour dégager le nom du sort."] = "Badges can appear above tooltips. In the spellbook, categories sit just above BEST, LOW or ECO to keep spell names clear.",
  ["Une sélection d’astuces explique des combinaisons utiles : Jugement avec un sceau, Javelot de glace sur cible gelée, Prompte guérison avec un soin sur la durée, Nova de feu avec un totem de feu et Conflagration avec Immolation."] = "Selected hints explain useful combinations: Judgement with a Seal, Ice Lance against a frozen target, Swiftmend with a heal over time, Fire Nova with a Fire totem and Conflagrate with Immolate.",
  ["Certains talents du paladin indiquent les spécialisations conseillées avec leur icône et le contexte précis du build du guide. Les variantes situationnelles sont distinguées du build standard."] = "Selected Paladin talents show recommended specializations with their icons and the guide’s precise build context. Situational variants are distinguished from the standard build.",
  ["Les talents qui améliorent des sorts de zone présentent les sorts concernés avec leurs icônes et descriptions du jeu. Leur repère AOE décrit la mécanique, pas une obligation de choisir le talent."] = "Talents that improve area spells show the affected spells with their game icons and descriptions. Their AOE marker describes the mechanic, not a requirement to choose the talent.",
  ["Les rubriques de réglages sont accessibles dans la colonne de gauche d’Options → AddOns, sous Skills & More, pour laisser davantage de place au contenu."] = "Settings sections appear in the left-hand list of Options → AddOns under Skills & More, leaving more room for their content.",
  ["Les explications des badges et des conseils d’usage suivent la langue choisie, y compris hors du grimoire."] = "Badge explanations and usage advice follow the selected language, including outside the spellbook.",
  ["Dans TrainerSpells, les compétences de démons mémorisées affichent leur coche de sort appris, même avec des noms traduits ou des grimoires portant un autre ID."] = "In TrainerSpells, recorded demon abilities show their learned check even with translated names or grimoires using a different ID.",
  ["Les sorts de zone reconnus ne sont plus conseillés comme des achats OPTIONAL. Drain d’âme porte CLASS et conserve les conseils de rang adaptés sans être présenté comme un sort facultatif."] = "Recognized area spells are no longer recommended as OPTIONAL purchases. Drain Soul shows CLASS and retains appropriate rank advice without being presented as an optional spell.",
  ["Les catégories d’usage restent reconnues sur les différents rangs d’un sort. Protection divine est notamment reconnue à ses deux rangs."] = "Usage categories remain recognized across a spell’s ranks. Divine Protection is recognized at both ranks.",
  ["PATCHNOTES_LANGUAGE"] = "English",
  ["PATCHNOTES_FEATURES"] = "New features",
  ["PATCHNOTES_FIXES"] = "Bug fixes",
}
